async function submitContactForm(e){
  e.preventDefault();
  const form = document.getElementById('contactForm');
  const successMsg = document.getElementById('contactSuccessMsg');
  const errorMsg = document.getElementById('contactErrorMsg');
  successMsg.style.display = 'none';
  errorMsg.style.display = 'none';

  const formData = new FormData(form);
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 12000); // 12초 안에 응답 없으면 타임아웃 처리 (무한 로딩 방지)
    const response = await fetch(form.action, {
      method: 'POST',
      body: formData,
      headers: { 'Accept': 'application/json' },
      signal: controller.signal,
    }).finally(() => clearTimeout(timer));
    if (response.ok) {
      successMsg.style.display = 'block';
      form.reset();
    } else {
      errorMsg.style.display = 'block';
    }
  } catch (err) {
    errorMsg.style.display = 'block';
  }
  return false;
}

// 브라우저 탭 제목 — 뷰가 바뀔 때(go())뿐 아니라 같은 화면에 머문 채로 언어만 바꿀 때도
// (applyTranslations()) 항상 현재 언어로 다시 반영해야 함. 예전엔 go()에서만, 그것도 한국어
// 문구로 고정 세팅해서 영어·중국어로 보고 있어도 화면 전환마다 탭 제목이 한국어로 돌아가던 버그가 있었음
const PAGE_TITLES = {
  home: { ko: '미국 복권 세금 계산기 | 참택스 - 미국 파워볼·메가밀리언즈 실수령액', en: 'US Lottery Tax Calculator | ChamTax — Powerball & Mega Millions Take-Home', zh: '美国彩票税金计算器 | ChamTax — 强力球·超级百万实得金额' },
  compare: { ko: '미국 복권 이중과세·국가별 실수령액 비교 | 참택스', en: 'US Lottery Double Taxation & Country Comparison | ChamTax', zh: '美国彩票双重征税·各国实得金额对比 | ChamTax' },
  odds: { ko: '미국 파워볼 당첨 확률 체감 | 참택스', en: 'US Powerball Odds, Visualized | ChamTax', zh: '美国强力球中奖概率体验 | ChamTax' },
  faq: { ko: '미국 복권 세금 FAQ - 이중과세·원천징수 | 참택스', en: 'US Lottery Tax FAQ — Double Taxation & Withholding | ChamTax', zh: '美国彩票税金FAQ — 双重征税·预扣税 | ChamTax' },
  privacy: { ko: '개인정보처리방침 | 참택스', en: 'Privacy Policy | ChamTax', zh: '隐私政策 | ChamTax' },
  disclaimer: { ko: '면책조항 | 참택스', en: 'Disclaimer | ChamTax', zh: '免责声明 | ChamTax' },
  contact: { ko: '문의하기 | 참택스', en: 'Contact | ChamTax', zh: '联系我们 | ChamTax' }
};

// PAGE_TITLES는 ko/en/zh 3개 언어만 공들여 따로 쓴 문구가 있고, 나머지 19개 언어는 커스텀
// 문구가 없어서 entry.ko(한국어)로 조용히 폴백하고 있었음 — "다국어 드롭다운을 하나씩 들어가서
// 번역이 다 되어있는지 확인해달라"는 요청으로 실제 렌더링해보다가 발견(2026-07-27, 19개
// 언어 × 7개 화면 = 133곳에서 탭 제목만 한국어로 고정 표시되고 있었음). 133개를 전부 새로
// 번역하는 대신, 이미 화면에 노출되어 검증된 다른 i18n 키(네비게이션 라벨 등)를 재사용해서
// "{짧은 이름} | ChamTax" 형태로 자동 구성함 — 새 번역 리스크 없이 22개 언어 전부 커버됨
const PAGE_TITLE_KEYS = {
  home: 'hero.tag', compare: 'nav.compare', odds: 'nav.odds', faq: 'nav.faq',
  privacy: 'privacy.breadcrumb', disclaimer: 'disclaimer.breadcrumb', contact: 'contact.breadcrumb',
};

function applyCurrentViewTitle(view){
  const entry = PAGE_TITLES[view];
  if (!entry) return;
  if (entry[currentLang]) { document.title = entry[currentLang]; return; }
  if (currentLang === 'ko') { document.title = entry.ko; return; }
  const key = PAGE_TITLE_KEYS[view];
  const label = key && resolveI18n(key);
  // hero.tag만 "🧮 US Lottery Tax Calculator"처럼 이모지 접두어가 붙어있어 탭 제목에는 안 어울려
  // 떼어냄(나머지 키는 애초에 이모지가 없음). resolveI18n이 실패하면(있을 수 없지만 방어적으로)
  // entry.ko까지 그대로 폴백
  const cleanLabel = label && view === 'home' ? label.replace(/^\S+\s+/, '') : label;
  document.title = cleanLabel ? `${cleanLabel} | ChamTax` : entry.ko;
}

// <meta name="description">가 언어 전환과 무관하게 HTML에 박힌 한국어 문구로 항상 고정돼있던
// 문제(2026-07-29, "언어별 SEO 노출" 점검 중 발견 — <title>/<html lang>은 이미 언어별로
// 갱신되고 있었는데 이 태그만 빠져있었음). 구글이 검색결과 스니펫에 이 태그를 그대로 쓸 수도
// 있어서, hreflang으로 다른 언어 검색결과에 노출되더라도 스니펫은 한국어로 보이는 불일치가
// 있었음. PAGE_TITLES와 같은 원칙: ko/en/zh(가장 트래픽이 큰 3개 핵심 언어)만 직접 새로
// 써주고, 나머지 언어는 새 번역 리스크 없이 이미 검증된 hero.tag+hero.title(광고 문구용으로
// 이미 쓰이는 짧은 문장들)을 조합해서 최소한 그 언어로는 보이게 함 — 완벽한 맞춤 설명은
// 아니지만 "한국어 고정" 문제는 해결됨
const PAGE_DESCRIPTIONS = {
  home: {
    ko: '미국 복권(파워볼·메가밀리언즈) 당첨 시 세금과 실수령액을 확인해보세요. 한국 거주자 이중과세, 미국 비거주자 원천징수까지 한 번에 계산해볼 수 있어요.',
    en: 'Calculate US Powerball & Mega Millions after-tax take-home instantly — nonresident withholding, Korea double-taxation, and more, all in one place.',
    zh: '立即计算美国强力球·超级百万彩票中奖后的税后实得金额 — 涵盖非居民预扣税、韩国双重征税等。',
  },
};

function applyCurrentViewDescription(view){
  const metaEl = document.querySelector('meta[name="description"]');
  if (!metaEl) return;
  const entry = PAGE_DESCRIPTIONS[view];
  if (entry && entry[currentLang]) { metaEl.setAttribute('content', entry[currentLang]); return; }
  if (entry && currentLang === 'ko') { metaEl.setAttribute('content', entry.ko); return; }
  // 커스텀 문구가 없는 화면/언어는 hero.tag(짧은 태그라인)+hero.title(질문형 한 줄, <br> 포함이라
  // 공백으로 치환)을 이어붙여 최소한의 설명형 문장을 만듦 — 둘 다 이미 22개 언어 전부 채워진
  // 검증된 키라 새 번역 없이 안전하게 재사용 가능
  const tag = resolveI18n('hero.tag');
  const titleHtml = resolveI18n('hero.title');
  const titleText = titleHtml ? titleHtml.replace(/<br\s*\/?>/gi, ' ').trim() : '';
  const combined = [tag, titleText].filter(Boolean).join(' — ');
  if (combined) { metaEl.setAttribute('content', combined); return; }
  if (entry) metaEl.setAttribute('content', entry.ko);
}

function go(view){
  document.querySelectorAll('.view').forEach(v => v.classList.remove('on'));
  document.getElementById('view-' + view).classList.add('on');
  setupRevealAnimation();
  document.getElementById('nav-compare').classList.toggle('active', view === 'compare');
  document.getElementById('nav-odds').classList.toggle('active', view === 'odds');
  document.getElementById('nav-faq').classList.toggle('active', view === 'faq');
  applyCurrentViewTitle(view);
  applyCurrentViewDescription(view);

  // 도움말(FAQ) 검색 플로팅 버튼은 이미 도착해있는 도움말 화면에서까지 떠 있을 필요가 없어서
  // 그 화면에서만 숨김 (다른 모든 화면에서는 계속 떠 있음)
  const faqFloatWrap = document.getElementById('faqFloatWrap');
  if (faqFloatWrap) faqFloatWrap.classList.toggle('is-hidden', view === 'faq');
  // 탭을 바꾸면 스크롤 위치는 그대로인데 그 아래 콘텐츠는 통째로 바뀌므로(스크롤 이벤트가
  // 안 남) 겹침 여부를 여기서도 다시 확인해야 함
  requestAnimationFrame(updateFaqFloatBtnVisibility);

  // 홈 ↔ 국가비교 이동 시, 어느 쪽에서 왔든 상관없이 항상 공용 상태(sharedAmountUsd/sharedCountry/EXCHANGE_RATE)를
  // 기준으로 화면을 다시 그려서 입력값·환율이 끊기지 않게 함
  if (view === 'home') {
    syncHomeFromShared();
    // 다른 페이지에서 언어를 전환한 뒤 홈으로 돌아오는 경우에도 잭팟 패널·추첨 카운트다운이
    // 항상 현재 언어로 보이도록 재적용 (언어 전환 시점에 홈 화면이 아니면 안 갱신되던 문제)
    applyJackpotData();
    updateDrawCountdown();
    setupStickyResultBadge();
  } else {
    // 홈이 아닌 다른 탭으로 이동하면, IntersectionObserver 콜백이 아직 안 돌았어도
    // 즉시 숨겨서 다른 화면에 실수령액 배지가 잠깐이라도 겹쳐 보이지 않게 함
    const badge = document.getElementById('sticky-result-badge');
    if (badge) badge.classList.remove('is-visible');
  }
  if (view === 'compare') {
    syncCompareFromShared();
  } else if (view === 'faq') {
    // 국가 토글을 한 번도 안 건드린 상태로 FAQ 탭을 바로 누르면 filterFaq()가 아직 한 번도
    // 실행된 적이 없어서, 세금 기준(kr/us/cn)과 무관한 질문까지 전부 보이던 버그가 있었음
    filterFaq();
  } else if (view === 'odds') {
    renderOddsTabDataWhenReady();
    // 2026-07-26: 날짜별 당첨번호 조회 위젯은 odds 탭 DOM 안에만 있지만, 초기화 함수
    // (updateDateLookupUi -> setupDateLookup -> renderDateLookupResult)가 DOMContentLoaded에서
    // 무조건 호출되고 있어서 이 탭을 열어본 적 없는 방문자도 odds-data.js(492KB)를 강제로
    // 받아가고 있었음(2026-07-22 지연로드 최적화가 실질적으로 무효화된 상태 — Playwright
    // 성능 측정으로 발견). 다른 지연로드 호출들과 동일하게 이 탭을 처음 열 때만 실행하도록 이동.
    // setupDateLookup()은 yearSel.dataset.wired로 한 번만 실제 초기화되므로 여러 번 호출해도 안전
    updateDateLookupUi();
  }

  document.querySelector('.page').scrollIntoView({behavior:'smooth', block:'start'});
}

// 확률체감 탭 전용 대용량 데이터(파워볼/메가밀리언즈 역대 당첨번호·잭팟 아카이브, odds-data.js)는
// 홈/비교/FAQ만 보는 방문자에겐 필요 없어서, 이 탭을 처음 열 때만 받아오도록 지연 로드함
// (2026-07-22 성능 개선 — 이 데이터가 script.js 전체 용량의 상당 부분을 차지했음). 로드 전에도
// renderJackpotHistory() 등은 안전하게 호출될 수 있고(각 함수가 데이터 미로드 시 조용히 스킵),
// 로드가 끝나면 여기서 다시 호출해 실제로 채움
let _oddsDataLoadPromise = null;
function ensureOddsDataLoaded(){
  if (_oddsDataLoadPromise) return _oddsDataLoadPromise;
  _oddsDataLoadPromise = new Promise((resolve, reject) => {
    if (typeof JACKPOT_HISTORY !== 'undefined') { resolve(); return; }
    const script = document.createElement('script');
    script.src = 'odds-data.js?v=20260728';
    script.onload = () => resolve();
    script.onerror = () => reject(new Error('odds-data.js failed to load'));
    document.head.appendChild(script);
  });
  return _oddsDataLoadPromise;
}

function renderOddsTabDataWhenReady(){
  ensureOddsDataLoaded().then(() => {
    renderJackpotHistory();
    renderJackpotTakeHomeRanking();
    renderJackpotIndexRollover();
    renderJackpotIndexCpiRanking();
    renderNumberFrequencyStats();
  }).catch(err => console.error('[odds-data]', err));
}

// "나는 어떤 경우일까요?" 패널은 첫 방문자에게만 기본 펼침으로 보여줌(2026-07-25 결정,
// 재외국민/외국인 방문자가 자기 경우를 못 찾고 이탈하는 것 방지) — 다만 매번 다시 펼쳐서
// 보여주면 재방문자에게는 첫 화면이 불필요하게 길어 보인다는 피드백(2026-07-30, 모바일
// 정보 밀도 점검)을 받아, 한 번이라도 이 패널을 본 적 있는 사람에게는 다음 방문부터 기본
// 접힘으로 시작하게 함. localStorage 접근 실패(사파일 프라이빗 모드 등)는 조용히 무시 —
// 실패해도 "매번 펼쳐 보이는" 기존 동작으로만 되돌아갈 뿐 기능이 깨지진 않음
function collapseIntroPersonaForReturningVisitors(){
  const accordion = document.getElementById('introPersonaAccordion');
  if (!accordion) return;
  try {
    if (localStorage.getItem('introPersonaSeen')) accordion.open = false;
    else localStorage.setItem('introPersonaSeen', '1');
  } catch(e) {}
}
document.addEventListener('DOMContentLoaded', collapseIntroPersonaForReturningVisitors);

// "나는 어떤 경우일까요?" 안내 배너에서 "한국에 살아요" 카드를 누르면, 배너를 접고
// 바로 아래 입력창으로 스크롤해줌 — 이미 홈 화면에 있으니 페이지 이동은 필요 없음
function goToCalculatorInput(){
  const accordion = document.getElementById('introPersonaAccordion');
  if (accordion) accordion.open = false;
  const inputCard = document.querySelector('.input-card');
  if (inputCard) inputCard.scrollIntoView({behavior:'smooth', block:'start'});
}

// "실제로 다른 나라에 살아요" 카드의 US/CN 버튼 — 한국이랑 아무 상관없는 진짜 외국인(예: 순수
// 미국인·중국인)을 위한 원클릭 진입점. 언어와 세금 기준을 그 나라에 맞게 한 번에 맞춰주고
// 계산기로 스크롤함 — 이게 없으면 한국어 화면만 보고 이탈할 위험이 있었음
function goToRealAbroad(country, lang){
  setLanguage(lang, true);
  setHomeCountry(country);
  goToCalculatorInput();
}

// 언어/국가 버튼 그리드를 드롭다운으로 압축한 UI용 — 선택된 <option>의 value를 보고
// 언어 전환(setLanguage) 또는 별도 페이지 이동(location.href) 중 하나로 분기
function goWithLangSelect(selectId){
  const sel = document.getElementById(selectId);
  if (!sel) return;
  const val = sel.value;
  if (val.startsWith('href:')) {
    location.href = val.slice(5);
  } else {
    setLanguage(val, true);
    goToCalculatorInput();
  }
}

// "다른 나라에 살아요" 드롭다운(국가|언어 값)을 goToRealAbroad로 연결
function goRealAbroadFromSelect(selectId){
  const sel = document.getElementById(selectId);
  if (!sel) return;
  const [country, lang] = sel.value.split('|');
  goToRealAbroad(country, lang);
}

function formatAbbreviatedUsd(value){
  if (value >= 1e9) return (value / 1e9).toFixed(1) + 'B';
  if (value >= 1e6) return (value / 1e6).toFixed(0) + 'M';
  return Math.round(value).toLocaleString('en-US');
}

function animateCount(el, target, opts) {
  opts = opts || {};
  const duration = 900;
  const start = performance.now();
  const prefix = opts.prefix || '';
  const suffix = opts.suffix || '';
  const decimals = opts.decimals || 0;
  function frame(now) {
    const progress = Math.min((now - start) / duration, 1);
    const eased = 1 - Math.pow(1 - progress, 3); // ease-out
    const value = target * eased;
    const formatted = opts.abbreviate
      ? formatAbbreviatedUsd(value)
      : decimals > 0
        ? value.toFixed(decimals)
        : Math.round(value).toLocaleString('en-US');
    el.textContent = prefix + formatted + suffix;
    if (progress < 1) requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
}

// "이 돈이면 뭘 살 수 있을까요" 카드(강남 아파트/페라리/스타벅스 등, updateFlexBox)용 범용 카운트업.
// animateCount()는 "$"+축약 표기(USD 전용)를 전제로 하지만, 여기는 "108채"/"하루 3잔씩 N년"처럼
// 언어별 완성 문장 안에 숫자만 끼워 넣는 형태라 서식을 직접 못 박아둘 수 없음 — 그래서 서식을
// buildText(현재값)라는 콜백으로 호출부가 결정하게 함(가장 가벼운 형태의 공통 모션이라 국가·
// 문구별로 매번 새로 만들 필요 없음, 2026-07-27).
function animateFlexNumber(el, target, buildText, duration){
  if (!el) return;
  duration = duration || 700;
  const start = performance.now();
  function frame(now){
    // rAF 콜백의 now가 드물게 start보다 아주 살짝 앞선 값으로 들어올 때가 있어서(프레임 경계
    // 타이밍 오차), 그대로 두면 progress가 미세하게 음수가 되고 Math.floor가 그걸 -1로
    // 내림해버려 "-1채"처럼 잠깐 마이너스로 보이는 버그가 있었음(Playwright로 실제 재현) —
    // 0 이상으로 고정해서 막음
    const progress = Math.min(1, Math.max(0, (now - start) / duration));
    const eased = 1 - Math.pow(1 - progress, 3); // ease-out, animateCount()와 동일한 완급
    el.textContent = buildText(Math.floor(target * eased));
    if (progress < 1) requestAnimationFrame(frame);
    else el.textContent = buildText(target);
  }
  requestAnimationFrame(frame);
}

function runCountUps() {
  document.querySelectorAll('.countup').forEach(el => {
    const target = Number(el.getAttribute('data-target'));
    animateCount(el, target, { prefix: '$', abbreviate: true });
  });
  document.querySelectorAll('.countup-dec').forEach(el => {
    const target = Number(el.getAttribute('data-target'));
    const suffix = el.getAttribute('data-suffix') || '';
    animateCount(el, target, { suffix, decimals: 1 });
  });
}

function usdToKrwLabel(usd){
  const krw = usd * EXCHANGE_RATE;
  if (typeof currentLang !== 'undefined' && currentLang === 'en') {
    return '(≈ ' + formatWonEn(krw / 100000000) + ')';
  }
  if (typeof currentLang !== 'undefined' && currentLang === 'vi') {
    return '(≈ ' + formatWonVi(krw / 100000000) + ')';
  }
  if (typeof currentLang !== 'undefined' && currentLang === 'th') {
    return '(≈ ' + formatWonTh(krw / 100000000) + ')';
  }
  if (typeof currentLang !== 'undefined' && currentLang === 'ru') {
    return '(≈ ' + formatWonRu(krw / 100000000) + ')';
  }
  if (typeof currentLang !== 'undefined' && currentLang === 'ja') {
    return '(≈ ' + formatWonJa(krw / 100000000) + ')';
  }
  // 억 단위로 먼저 반올림한 뒤 조/억을 나누면, "999.6억이 반올림되며 조 단위를 못 넘어가는" 이월 누락 문제가 안 생김
  const totalEok = Math.round(krw / 100000000);
  const 조 = Math.floor(totalEok / 10000);
  const 억 = totalEok % 10000;
  // 중국어도 亿(=억) 단위 체계가 같아서, "조" 자리만 현대 중국어 관행상 "万亿"(만조)으로 표기
  if (typeof currentLang !== 'undefined' && currentLang === 'zh') {
    if (조 > 0 && 억 === 0) return `(约${조}万亿韩元)`;
    if (조 > 0) return `(约${조}万亿${억.toLocaleString('zh-CN')}亿韩元)`;
    return `(约${억.toLocaleString('zh-CN')}亿韩元)`;
  }
  // formatWon()과 같은 원칙: 위에서 처리 안 된 나머지 모든 언어(크메르어·네팔어·우즈베크어·
  // 몽골어·카자흐어·키르기스어·우르두어·벵골어·라오어·아랍어·힌디어·프랑스어·타갈로그어 등)는
  // "억/조"라는 한국식 단위 대신 훨씬 널리 통하는 영어식 million/billion으로 통일함 —
  // 이 함수(usdToKrwLabel)는 formatWon()과 별개라 그 수정이 안 들어가 있었고, 그 결과 이 언어들의
  // 잭팟 퀵필 버튼에서만 "억원"이 그대로 노출되고 있었음
  if (typeof currentLang !== 'undefined' && currentLang !== 'ko') {
    return '(≈ ' + formatWonEn(krw / 100000000) + ')';
  }
  if (조 > 0 && 억 === 0) return `(약 ${조}조원)`;
  if (조 > 0) return `(약 ${조}조 ${억.toLocaleString('ko-KR')}억원)`;
  return `(약 ${억.toLocaleString('ko-KR')}억원)`;
}

// 2026-07-25: "잭팟 카드 기준 게임" 토글(odds-game-pb/odds-game-mega)이 있는데도 이 함수가
// jp-powerball만 고정으로 읽어서, 메가밀리언즈로 토글해도 위 "🏆 잭팟" 카드가 계속 파워볼
// 금액을 보여주는 버그가 있었음(사용자 지적 — "메가밀리언즈 1등은 어떻게 되는거야?"). 인자로
// 게임을 받아 currentOddsGame을 기본값으로 씀
function getJackpotKRW(game){
  const targetId = (game || currentOddsGame) === 'megamillions' ? 'jp-mega' : 'jp-powerball';
  const usd = Number(document.getElementById(targetId).getAttribute('data-target'));
  return usd * EXCHANGE_RATE;
}

// jackpot-card-odds-num에 들어가는 "1 / N" 확률 표기 — odds.oddsPowerball 번역키와 같은
// 스타일(언어별 단위 관례: 억/만, M, 亿, करोड़ 등)로 메가밀리언즈(1/290,472,336)도 맞춤.
// 2026-07-29: 메가밀리언즈가 2025년 4월에 티켓 5달러·번호 매트릭스 개편을 거치면서 확률이
// 1/302,575,350에서 1/290,472,336으로 바뀌었는데, 이 함수는 그 개편 전 숫자(1/303M 등)가
