function renderJackpotTakeHomeRanking(){
  const listEl = document.getElementById('jh-rank-list');
  if (!listEl) return;
  const titleEl = document.getElementById('jh-rank-title');
  const descEl = document.getElementById('jh-rank-desc');
  if (titleEl) titleEl.textContent = pickLang(
    '🏆 발표 금액 말고, 실제로 손에 쥐는 돈 기준으로 다시 줄 세우면?',
    '🏆 What if we ranked by actual take-home, not the announced amount?',
    '🏆 如果不按发布金额，而按实际到手金额重新排名呢？',
    '🏆 Nếu xếp hạng theo số tiền thực nhận, chứ không phải số tiền công bố thì sao?',
    '🏆 ถ้าจัดอันดับตามเงินที่ได้รับจริง ไม่ใช่จำนวนที่ประกาศล่ะ?',
    '🏆 А что если ранжировать по реальной сумме на руки, а не по объявленной?',
    JH_RANK_TITLE_MORE
  );
  // 랭킹 자체(getJackpotRealTakeHomeRanking)뿐 아니라 이 설명 문구도 실제 선택된 세금 기준을
  // 따라야 함 — calcTakeHome()이 나라별로 이미 22개 언어 전부 커버해 돌려주는 basisSuffix
  // ("한국 거주자"/"China resident (living in China)" 등, pickLang으로 현재 언어에 맞게 이미
  // 해석된 문자열)를 그대로 문장 끝에 덧붙임. amount 인자는 basisSuffix 값 자체에 영향을 주지
  // 않으므로(나라별 분기 어디서도 금액에 따라 문구가 안 바뀜) 아무 값이나 넣어도 안전함
  const basisSuffix = calcTakeHome(1, sharedCountry, sharedState).basisSuffix;
  if (descEl) descEl.textContent = pickLang(
    `발표 잭팟(연금) 순위가 아니라, 오늘 세율로 실제 받는 금액 기준 TOP 10이에요 · ${basisSuffix}`,
    `Not ranked by the announced (annuity) jackpot — this is the TOP 10 by what's actually taken home under today's tax rates · ${basisSuffix}`,
    `不是按发布的（年金）头奖排名，而是按今天税率下实际到手金额排出的TOP 10 · ${basisSuffix}`,
    `Không xếp theo jackpot công bố (trả góp) — đây là TOP 10 theo số tiền thực nhận theo thuế suất hôm nay · ${basisSuffix}`,
    `ไม่ได้จัดอันดับตามแจ็คพอตที่ประกาศ(แบบผ่อน) — นี่คือ TOP 10 ตามจำนวนเงินที่ได้รับจริงตามอัตราภาษีวันนี้ · ${basisSuffix}`,
    `Ранжировано не по объявленному (аннуитетному) джекпоту — это ТОП-10 по сумме, которую реально получают на руки по сегодняшним налоговым ставкам · ${basisSuffix}`,
    buildRankDescMore(basisSuffix)
  );
  const changeBasisLinkEl = document.getElementById('jh-rank-change-basis-link');
  if (changeBasisLinkEl) changeBasisLinkEl.textContent = pickLang(
    '🔧 세금 기준 바꾸기 →', '🔧 Change tax basis →', '🔧 更改税收基准 →',
    '🔧 Đổi cơ sở thuế →', '🔧 เปลี่ยนฐานภาษี →', '🔧 Изменить налоговую базу →'
  );

  const gameNameKo = { powerball: '파워볼', megamillions: '메가밀리언즈' };
  const gameNameEn = { powerball: 'Powerball', megamillions: 'Mega Millions' };
  const gameNameZh = { powerball: '强力球', megamillions: '超级百万' };
  const gameNameVi = { powerball: 'Powerball', megamillions: 'Mega Millions' };
  const gameNameTh = { powerball: 'พาวเวอร์บอล', megamillions: 'เมกะมิลเลียน' };
  const gameNameRu = { powerball: 'Powerball', megamillions: 'Mega Millions' };
  const medals = ['🥇', '🥈', '🥉'];

  const rankCtaLabel = jackpotRankCtaLabel();
  listEl.innerHTML = getJackpotRealTakeHomeRanking(10).map(({ entry, announcedKrw, cashUsd, takeHome }, i) => {
    const gameLabel = pickLang(gameNameKo[entry.game], gameNameEn[entry.game], gameNameZh[entry.game], gameNameVi[entry.game], gameNameTh[entry.game], gameNameRu[entry.game], GAME_NAME_MORE[entry.game]);
    const gameTagClass = entry.game === 'powerball' ? 'pb' : 'mm';
    const gameTagEmoji = entry.game === 'powerball' ? '🔴' : '🟡';
    const rankBadge = medals[i] || `${i + 1}`;
    // RTL 언어(아랍어·우르두어)에서 방향 지정 없는 금액 문자열이 브라우저 bidi 알고리즘에
    // 의해 어순이 뒤집혀 보이는 문제(위 아키텍처 패턴 섹션의 nowrap span 사례와 같은 종류의
    // bidi 버그) — <bdi>로 감싸서 항상 하나의 방향 단위로 렌더링되게 함(2026-07-24 발견·수정)
    const announcedAmt = `<bdi>${formatEokKrwInDisplayCurrency(announcedKrw / 100000000, sharedInputCurrency)}</bdi>`;
    const announcedLine = pickLang(
      `발표액 ${announcedAmt}`, `Announced ${announcedAmt}`,
      `发布金额 ${announcedAmt}`, `Công bố ${announcedAmt}`,
      `ประกาศ ${announcedAmt}`, `Объявлено ${announcedAmt}`,
      buildAnnouncedLineMore(announcedAmt)
    );
    return `<div class="jh-rank-row">
      <span class="jh-rank-medal">${rankBadge}</span>
      <div class="jh-rank-body">
        <div class="jh-rank-top">
          <span class="jh-rank-date">${entry.date}</span>
          <span class="jh-game-tag ${gameTagClass}">${gameTagEmoji} ${gameLabel}</span>
        </div>
        <div class="jh-rank-amt"><bdi>${formatEokKrwInDisplayCurrency(takeHome, sharedInputCurrency)}</bdi></div>
        <div class="jh-rank-sub">${announcedLine}</div>
        <button type="button" class="jh-rank-cta" onclick="fillHomeAmountFromRanking(${Math.round(cashUsd)})">${rankCtaLabel}</button>
      </div>
    </div>`;
  }).join('');
}

// ==================== 🏆 ChamTax 잭팟 인덱스 (2026-07-24 신규) ====================
// "발표 금액"이 아니라 다른 두 축으로 역대 잭팟을 다시 보여주는 콘텐츠 — 경쟁 복권 통계
// 사이트는 미국 세율만 다루거나 세금 계산 자체를 안 해서 이 조합(세금 계산기 + 역대 아카이브)을
// 못 만듦. 자세한 기획 배경은 differentiation_request.md 논의 참고.
//
// (A) 이월(Rollover) 스트릭: POWERBALL_JACKPOT_ARCHIVE/MEGAMILLIONS_JACKPOT_ARCHIVE(둘 다
//     odds-data.js, 회차별 실제 발표 금액 포함 — 파워볼 1992-04-22~, 메가밀리언즈 1996-09-20~
//     최신까지 전 회차 커버 확인함, 2026-07-24)를 그대로 재사용. 새로운 외부 데이터가 전혀
//     필요 없고 이미 검증된 아카이브에서 "연속 증가 구간"만 계산하는 순수 파생 로직이라
//     신뢰도 리스크가 없음 — 실제로 2022-11-07 파워볼 역대 최고액($2,040.1M)과 2023-08-08
//     메가밀리언즈 역대 2위($1,602M)가 알고리즘상 최장 스트릭 상위권에 그대로 다시 잡히는 것으로
//     교차 확인함(이미 알려진 실제 사건과 일치).
// (B) 물가보정 실질가치 랭킹: 미 BLS CPI-U 연평균 지수로 보정. 이 실행 환경은 외부 인터넷이
//     막혀있어(WebFetch로 bls.gov/FRED/위키피디아 전부 403 확인함, 2026-07-24) 이 세션이 직접
//     조회는 못 했으나, 사용자가 별도로 제미나이에 검증을 요청해 대조받음(2026-07-24) — 아래
//     US_CPI_ANNUAL 표의 10개 값 전부 BLS 공식 연평균(Series ID CUUR0000SA0, CPI-U 전체 도시
//     소비자, 1982-84=100, 비계절조정)과 소수점 첫째 자리까지 일치 확인됨. 2025년 연평균은
//     제미나이도 "확정 불가"로 답변해서 표에 넣지 않음 — CPI_BASE_YEAR 이후 연도는 자동으로
//     랭킹에서 제외되는 안전장치가 이미 있으므로 문제 없음. "체험용 시뮬레이션" 문구는 수치
//     불확실성 때문이 아니라(이제 검증됨) 세율·환율·일시불 비율 등 여러 가정이 섞인 계산이라는
//     점을 알리기 위해 계속 유지함.
function getRolloverStreaks(archive){
  if (!archive || !archive.length) return [];
  const sorted = [...archive].sort((a, b) => a[0].localeCompare(b[0]));
  const streaks = [];
  let cur = null;
  for (const [date, , , amountMillions] of sorted) {
    if (cur && amountMillions >= cur.prevAmt) {
      cur.count++;
      cur.endDate = date;
      cur.peakAmountMillions = amountMillions;
    } else {
      if (cur) streaks.push(cur);
      cur = { startDate: date, endDate: date, count: 1, peakAmountMillions: amountMillions };
    }
    cur.prevAmt = amountMillions;
  }
  if (cur) streaks.push(cur);
  return streaks;
}

function getTopRolloverStreaks(topN){
  if (typeof POWERBALL_JACKPOT_ARCHIVE === 'undefined') return []; // odds-data.js 로드 전
  const combined = [
    ...getRolloverStreaks(POWERBALL_JACKPOT_ARCHIVE).map(s => ({ ...s, game: 'powerball' })),
    ...getRolloverStreaks(MEGAMILLIONS_JACKPOT_ARCHIVE).map(s => ({ ...s, game: 'megamillions' })),
  ];
  return combined.sort((a, b) => b.count - a.count || b.peakAmountMillions - a.peakAmountMillions).slice(0, topN);
}

