// score(0~6) -> 톤 문구. 배열 인덱스는 그대로 score(0,1은 같은 문구 공유하려고 인덱스 보정)
function mnToneLine(score){
  const idx = score <= 1 ? 0 : score - 1; // 0,1 -> 0번째 문구, 2->1번째, ... 6->5번째
  return pickLang(...MN_TONE_TIERS[idx]);
}

