// JACKPOT_HISTORY(당첨번호 확인된 역대급 5건, isLegendary=true) + POWERBALL_DRAW_ARCHIVE/
// MEGAMILLIONS_DRAW_ARCHIVE(각각 1992-04-22/2002-05-17부터 최신 회차까지 전체, 6300건+ —
// 2026-07-23 백필로 기존 2200건+에서 확장됨)를 합쳐 비교 대상 목록을 만듦. numbers/special
// 필드가 없는 JACKPOT_HISTORY 항목(대부분의 일반 기록)은
// 자동으로 제외됨. 아카이브가 이미 최신 회차까지 포함하므로 LATEST_DRAW는 여기서 더 안 합침
// (그래도 홈 화면 "최신 당첨번호" 위젯에서는 LATEST_DRAW를 그대로 씀 — 그건 별개 용도)
function getMyNumbersComparableDraws(){
  if (typeof JACKPOT_HISTORY === 'undefined') return []; // odds-data.js 로드가 아직 안 끝난 극히 드문 경우
  const fromHistory = JACKPOT_HISTORY.filter(e => e.numbers && e.special).map(e => ({
    date: e.date, game: e.game, numbers: e.numbers, special: e.special, isLegendary: true,
  }));
  const legendaryDates = new Set(fromHistory.map(e => e.game + e.date));
  const fromArchive = [
    ...POWERBALL_DRAW_ARCHIVE.map(([date, numbers, special]) => ({ date, game: 'powerball', numbers, special, isLegendary: false })),
    ...MEGAMILLIONS_DRAW_ARCHIVE.map(([date, numbers, special]) => ({ date, game: 'megamillions', numbers, special, isLegendary: false })),
  ].filter(e => !legendaryDates.has(e.game + e.date));
  return [...fromHistory, ...fromArchive].sort((a, b) => b.date.localeCompare(a.date));
}

let lastMyNumbersCheck = null; // { mainNums, specialNum } — 언어 전환 시 결과 재렌더링용

// 입력값 검증 + 결과 렌더링 트리거. 버튼 onclick에서 호출됨
// 입력칸 6개를 읽어서 검증까지 하는 공용 함수 — checkMyNumbersVsHistory()와
// saveMyNumbersAsTicketImage()(2026-07-24 신규) 둘 다 "같은 번호 6개, 같은 검증 규칙"이 필요해서
// 분리함. 실패 시 mn-error에 이유를 채우고 null을 반환, 성공 시 mn-error를 비우고 값을 반환
function readAndValidateMyNumbers(){
  const errorEl = document.getElementById('mn-error');
  const mainNums = [];
  for (let i = 1; i <= 5; i++) {
    const raw = document.getElementById(`mn-main-${i}`).value;
    mainNums.push(raw === '' ? NaN : Number(raw));
  }
  const specialNum = (() => {
    const raw = document.getElementById('mn-special').value;
    return raw === '' ? NaN : Number(raw);
  })();

  // 검증: 5개 모두 1~69 정수·서로 다른 값, 파워볼은 1~26 정수 — 실제 파워볼 규칙(중복 불가)과 맞춰야
  // "이게 뭘 비교하는 거지" 하는 혼란이 없음
  const rangeValid = mainNums.every(n => Number.isInteger(n) && n >= 1 && n <= 69);
  const hasDuplicate = rangeValid && new Set(mainNums).size !== 5;
  const specialValid = Number.isInteger(specialNum) && specialNum >= 1 && specialNum <= 26;
  // 중복 숫자가 원인인 경우 "입력을 다 안 했나?"가 아니라 정확히 뭐가 문제인지 짚어줌
  // (사용자가 서로 다른 숫자 5개를 넣은 줄 알았는데 실수로 겹친 경우를 위한 별도 메시지)
  if (hasDuplicate) {
    errorEl.textContent = pickLang(
      '입력하신 일반번호에 중복된 숫자가 있어요 — 서로 다른 숫자 5개를 입력해주세요',
      'Some of your main numbers are repeated — please enter 5 different numbers',
      '您输入的普通号码有重复 — 请输入5个不同的号码',
      'Có số bị trùng trong 5 số chính bạn nhập — vui lòng nhập 5 số khác nhau',
      'เลขหลักที่กรอกมีตัวซ้ำกัน — กรุณากรอกเลข 5 ตัวที่ไม่ซ้ำกัน',
      'В введённых числах есть повтор — пожалуйста, введите 5 разных чисел',
      MN_DUPLICATE_ERROR_MORE
    );
    return null;
  }
  if (!rangeValid || !specialValid) {
    errorEl.textContent = pickLang(
      '일반번호 5개(1~69, 서로 다른 숫자)와 파워볼 번호(1~26)를 모두 입력해주세요',
      'Please enter all 5 main numbers (1–69, all different) and the Powerball number (1–26)',
      '请输入5个不同的普通号码（1~69）和1个强力球号码（1~26）',
      'Vui lòng nhập đủ 5 số chính (1–69, khác nhau) và số Powerball (1–26)',
      'กรุณากรอกเลขหลัก 5 ตัว (1-69 ต้องไม่ซ้ำกัน) และเลขพาวเวอร์บอล (1-26) ให้ครบ',
      'Пожалуйста, введите все 5 основных чисел (1–69, разные) и число Powerball (1–26)',
      MN_ERROR_MORE
    );
    return null;
  }
  errorEl.textContent = '';
  return { mainNums, specialNum };
}

function checkMyNumbersVsHistory(){
  const valid = readAndValidateMyNumbers();
  if (!valid) return;
  const { mainNums, specialNum } = valid;
  lastMyNumbersCheck = { mainNums, specialNum };
  // odds-data.js가 아직 로딩 중일 수 있어(날짜조회 위젯과 같은 이유, 2026-07-22) 로드 완료를
  // 기다렸다가 실제 비교 결과를 그림 — ensureOddsDataLoaded()는 이미 로드됐으면 즉시 resolve됨
  ensureOddsDataLoaded().then(() => renderMyNumbersResult(mainNums, specialNum));
}

// 2026-07-24 신규: 입력한 번호 6개로 "재미용 가상 티켓" 이미지를 만들어 다운로드시킴. 서버 없이
// 전부 클라이언트 Canvas로 직접 그림 — 참택스 로고가 찍힌 이미지가 카톡/SNS로 퍼지면 그 자체로
// 브랜드 노출이 되는 효과를 노림(사용자 요청, "지저분해지지 않게" 기존 위젯에 버튼만 추가하는
// 형태로 넣음). 실제 티켓처럼 보이면 "이게 진짜 구매한 티켓인 줄" 오해할 수 있어서, 큰 글씨로
// "가상 티켓" 문구를 넣어 명확히 함(사이트가 이미 "구매·중개 NO"를 신뢰 배지로 내세우고 있어서
// 이 원칙과 어긋나지 않게).
// 아래 "이미지로 저장" 함수 두 개(saveMyNumbersAsTicketImage/saveHomeResultAsImage)가 공유하는
// 캔버스 바코드 헬퍼(2026-07-28 결과 카드 리디자인 때 분리) — 둘 다 "실제처럼 보이되 오해는
// 없게"라는 같은 원칙을 쓰므로 시각 요소를 하나로 모아 중복을 없앰.
// (2026-07-28 후속 세션: saveHomeResultAsImage()는 "복권 티켓" 느낌에서 "대형 기념 수표(giant
// novelty check)" 느낌으로 다시 리디자인됨 — 그때 이 헬퍼 바로 아래 있던 별/절취선 전용 헬퍼
// 2개(drawTicketStar/drawTicketPerforation)는 saveHomeResultAsImage()에서만 쓰이던 코드라
// 함께 삭제함(grep으로 다른 참조 없음을 확인). drawDecorativeBarcode는
// saveMyNumbersAsTicketImage()가 계속 쓰므로 그대로 유지.)

// 곰 마스코트 아이콘을 Canvas 2D 경로 명령으로 직접 그림(2026-07-28 브랜드 마크 정정 세션 신규).
// 같은 날 앞선 "공유 기능 통일" 세션이 이 자리에 "🐻" 유니코드 이모지를 실제 로고인 줄 알고
// 그대로 썼는데, 렌더링해보면 흔한 갈색 털복숭이 곰 얼굴 이모지라 사이트의 실제 마스코트(흰/크림
// 얼굴 + 청록 테두리 + 검정 점눈 + 분홍 볼 + 작은 청록 미소, index.html 헤더 로고의 인라인
// `.mascot-mark` SVG, og-image.png도 이 SVG를 그대로 재사용해서 만듦)와 전혀 다른 그림이었음 —
// "실제 로고와 맞는지"를 그 세션이 확인 안 한 게 원인. 이 함수는 그 실제 SVG(viewBox 0 0 28 28,
// 타원 4개 + 원 4개 + 베지어 곡선 1개뿐인 단순한 도형)의 좌표를 그대로 옮겨 그린 것 — 비동기
// 이미지 로딩(new Image() + onload) 방식 대신 이 방식을 택한 이유는, 두 호출부
// (saveMyNumbersAsTicketImage/saveHomeResultAsImage)가 지금 완전히 동기 함수라 이미지 로딩을
// 끼워 넣으려면 두 함수와 openAnnotateOverlay() 연결부까지 비동기로 바꿔야 해서 위험이 큰 반면,
// 도형 자체가 단순해서 Canvas 2D 경로만으로도 원본과 동일하게 재현 가능하기 때문.
// x0,y0: 아이콘의 좌상단 좌표(스케일 적용 전 기준), size: 아이콘의 가로/세로 픽셀 크기.
function drawBearMascotIcon(ctx, x0, y0, size){
  const scale = size / 28; // 원본 SVG viewBox가 0 0 28 28
  const teal = '#155445';   // 사이트 브랜드 청록(이 두 카드에서 이미 쓰는 값과 동일)
  const faceFill = '#FFFFFF'; // 헤더 로고 라이트모드 기준(var(--card))과 동일
  const eyeDark = '#262420';  // 헤더 로고 라이트모드 기준(var(--text-dark))과 동일

  ctx.save();
  ctx.translate(x0, y0);
  ctx.scale(scale, scale);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // 귀 2개 — 회전된 타원(원본 SVG의 rotate(-24)/rotate(24) transform과 동일하게 ellipse()의
  // 회전 인자로 처리)
  [[6.1, 10.4, -24], [21.9, 10.4, 24]].forEach(([cx, cy, deg]) => {
    ctx.beginPath();
    ctx.ellipse(cx, cy, 2.7, 4, deg * Math.PI / 180, 0, Math.PI * 2);
    ctx.fillStyle = faceFill; ctx.fill();
    ctx.strokeStyle = teal; ctx.lineWidth = 1.7; ctx.stroke();
  });

  // 얼굴(원)
  ctx.beginPath();
  ctx.arc(14, 15.6, 9.7, 0, Math.PI * 2);
  ctx.fillStyle = faceFill; ctx.fill();
  ctx.strokeStyle = teal; ctx.lineWidth = 1.8; ctx.stroke();

  // 볼 홍조 2개
  ctx.fillStyle = 'rgba(240,169,140,0.55)';
  [[8.5, 17.5], [19.5, 17.5]].forEach(([cx, cy]) => {
    ctx.beginPath();
    ctx.ellipse(cx, cy, 1.6, 1.05, 0, 0, Math.PI * 2);
    ctx.fill();
  });

  // 눈 2개 — 검정 원 + 흰 하이라이트 점
  [[10.5, 14.4, 11.05, 13.85], [17.5, 14.4, 18.05, 13.85]].forEach(([ex, ey, hx, hy]) => {
    ctx.beginPath(); ctx.arc(ex, ey, 1.7, 0, Math.PI * 2);
    ctx.fillStyle = eyeDark; ctx.fill();
    ctx.beginPath(); ctx.arc(hx, hy, 0.5, 0, Math.PI * 2);
    ctx.fillStyle = '#fff'; ctx.fill();
  });

  // 코(타원)
  ctx.beginPath();
  ctx.ellipse(14, 17.75, 1.85, 1.3, 0, 0, Math.PI * 2);
  ctx.fillStyle = teal; ctx.fill();

  // 입 — 원본 SVG path "M14 19.1v0.55M9.6 19.8c1.3 2.15 7.5 2.15 8.8 0"를 그대로 옮김
  // (세로 코 밑 점 + 좌우로 벌어지는 미소 곡선)
  ctx.beginPath();
  ctx.moveTo(14, 19.1);
  ctx.lineTo(14, 19.65);
  ctx.moveTo(9.6, 19.8);
  ctx.bezierCurveTo(10.9, 21.95, 17.1, 21.95, 18.4, 19.8);
  ctx.strokeStyle = teal;
  ctx.lineWidth = 1.4;
  ctx.stroke();

  ctx.restore();
}

// 곰 마스코트 아이콘 + "참택스" 워드마크를 함께 그림(2026-07-28 브랜드 마크 정정 세션 신규).
// 아이콘은 항상 텍스트보다 먼저(읽는 방향 기준 앞쪽에) 오고, 정렬 방향과 무관하게 "블록의 바깥쪽
// 가장자리"가 x좌표에 맞춰짐 — align='left'면 아이콘 왼쪽 끝이 x, align='right'면 텍스트 오른쪽
// 끝이 x(이전에 "🐻 참택스" 한 문자열을 fillText할 때와 같은 시각적 결과: 문자열은 항상 내부적으로
// LTR이라 이모지가 먼저 나오고, textAlign만 카드 왼쪽/오른쪽 어느 모서리에 붙일지 정했음). 호출 후
// ctx.textAlign은 align 값으로 남아있어 바로 이어지는 다른 fillText(예: 도메인 줄)에도 재사용 가능.
function drawLogoMark(ctx, text, x, y, align, opts){
  opts = opts || {};
  const iconSize = opts.iconSize || 28;
  const gap = opts.gap || 8;
  const font = opts.font || "700 30px 'Pretendard', -apple-system, sans-serif";
  const color = opts.color || '#155445';

  ctx.font = font;
  const textWidth = ctx.measureText(text).width;

  let iconX0, textX;
  if (align === 'right') {
    textX = x; // textAlign='right'로 그리므로 x는 곧 텍스트 블록의 오른쪽 끝
    iconX0 = x - textWidth - gap - iconSize;
  } else {
    iconX0 = x;
    textX = x + iconSize + gap;
  }

  // 2026-07-31: 마스코트 아이콘(drawBearMascotIcon)은 실제 사이트 헤더와 똑같이 "청록 테두리
  // + 흰 얼굴"로 그려짐 — 밝은 배경 위에서만 테두리가 또렷하게 보임. buildShareCard()/
  // saveHomeResultAsImage()의 청록 그러데이션 헤더 밴드 위에 그대로 쓰면 테두리가 배경에
  // 묻혀서 이목구비 경계가 흐릿해지는 문제가 실제로 있었음(사용자가 직접 확인·제보) — 아이콘
  // 뒤에 옅은 흰색 배지 원을 깔아서, 밴드 색과 무관하게 항상 "밝은 배경 위 아이콘"과 동일한
  // 대비를 보장함.
  if (opts.onDarkBg) {
    ctx.beginPath();
    ctx.arc(iconX0 + iconSize / 2, y, iconSize / 2 + 4, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(255,255,255,0.94)';
    ctx.fill();
  }

  drawBearMascotIcon(ctx, iconX0, y - iconSize / 2, iconSize);

  ctx.fillStyle = color;
  ctx.font = font;
  ctx.textAlign = align;
  ctx.fillText(text, textX, y);
}

// 텍스트가 maxWidth를 넘으면 폰트 크기를 minSize까지 1px씩 줄여서 항상 카드 안에 들어오게 함
// (2026-07-28 후속 세션 신규, 수표 카드 리디자인 때 추가) — 26개 언어마다 같은 문구의 실제 렌더링
// 폭이 크게 다를 수 있어서(예: 독일어/러시아어류는 길고, 한자류는 짧음), 고정 폰트 크기만 믿으면
// 일부 언어에서만 카드 폭을 넘길 위험이 있음. 호출 후 ctx.font가 이미 맞는 크기로 설정된
// 상태이므로 곧바로 fillText할 수 있음.
function fitFontSize(ctx, text, weight, maxSize, minSize, maxWidth){
  let size = maxSize;
  ctx.font = `${weight} ${size}px 'Pretendard', -apple-system, sans-serif`;
  while (size > minSize && ctx.measureText(text).width > maxWidth) {
    size -= 1;
    ctx.font = `${weight} ${size}px 'Pretendard', -apple-system, sans-serif`;
  }
  return size;
}

function saveMyNumbersAsTicketImage(){
  const valid = readAndValidateMyNumbers();
  if (!valid) return;
  const { mainNums, specialNum } = valid;
  const isRtl = RTL_LANGS.includes(currentLang);

  // 배율 2x로 그려서 다운로드한 이미지가 확대해도 안 흐릿하게 함
  const SCALE = 2;
  const W = 900, H = 460;
  const canvas = document.createElement('canvas');
  canvas.width = W * SCALE;
  canvas.height = H * SCALE;
  const ctx = canvas.getContext('2d');
  ctx.scale(SCALE, SCALE);

  // 2026-07-31 디자인팀 반영 가이드: 평평한 흰 배경+얇은 테두리 대신 다른 카드들과 통일된
  // 둥근 모서리(20px) 카드로 바꾸고, 로고를 상단 그러데이션 헤더 밴드로 옮김.
  const cardR = 20;
  ctx.beginPath();
  ctx.roundRect(0, 0, W, H, cardR);
  ctx.save();
  ctx.clip();
  ctx.fillStyle = '#FFFFFF';
  ctx.fillRect(0, 0, W, H);

  const bandH = 76;
  const bandGrad = ctx.createLinearGradient(0, 0, W, bandH);
  bandGrad.addColorStop(0, '#155445');
  bandGrad.addColorStop(1, '#1F6E5C');
  ctx.fillStyle = bandGrad;
  ctx.fillRect(0, 0, W, bandH);

  ctx.textBaseline = 'middle';
  drawLogoMark(ctx, '참택스 · ChamTax', isRtl ? W - 32 : 32, bandH / 2, isRtl ? 'right' : 'left', {
    iconSize: 30, gap: 10, font: "800 22px 'Pretendard', -apple-system, sans-serif", color: '#FFFFFF', onDarkBg: true
  });
  ctx.fillStyle = '#FFFFFF';
  ctx.font = "700 15px 'Pretendard', -apple-system, sans-serif";
  ctx.textAlign = isRtl ? 'left' : 'right';
  ctx.fillText('chamtax.com', isRtl ? 32 : W - 32, bandH / 2);

  ctx.restore(); // 클립 해제
  ctx.strokeStyle = '#E3E6EA';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.roundRect(1, 1, W - 2, H - 2, cardR);
  ctx.stroke();

  // 큰 제목("나만의 복권 티켓" 등)
  const title = pickLang('나만의 복권 티켓', 'My Lottery Ticket', '我的彩票', 'Vé số của tôi', 'ตั๋วลอตเตอรี่ของฉัน', 'Мой лотерейный билет', MN_TICKET_TITLE_MORE);
  ctx.fillStyle = '#262420';
  ctx.font = "800 26px 'Pretendard', -apple-system, sans-serif";
  ctx.textAlign = isRtl ? 'right' : 'left';
  ctx.fillText(title, isRtl ? W - 40 : 40, bandH + 40);

  // 번호 공(일반 5개 + 파워볼 1개) — 항상 가운데 정렬, 왼쪽부터 순서대로(방향 무관 — 숫자 순서 자체가
  // 의미 있는 정보라 RTL이어도 안 뒤집음, 실제 복권 번호 표기 관례를 따름)
  const balls = [...mainNums, specialNum];
  const ballR = 34, ballGap = 20;
  const totalW = balls.length * (ballR * 2) + (balls.length - 1) * ballGap;
  let bx = (W - totalW) / 2 + ballR;
  const by = bandH + 140;
  balls.forEach((n, i) => {
    ctx.beginPath();
    ctx.arc(bx, by, ballR, 0, Math.PI * 2);
    ctx.fillStyle = i === balls.length - 1 ? '#C0392B' : '#262420';
    ctx.fill();
    ctx.fillStyle = '#fff';
    ctx.font = "800 24px 'Pretendard', -apple-system, sans-serif";
    ctx.textAlign = 'center';
    ctx.fillText(String(n), bx, by + 2);
    bx += ballR * 2 + ballGap;
  });

  // 발행일 + "직접 선택" 메타 정보(실제 티켓의 QP(퀵픽) 표기 자리와 같은 위치·스타일)
  const today = new Date();
  const dateStr = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${String(today.getDate()).padStart(2, '0')}`;
  const selfPick = pickLang('직접 선택', 'Self-picked', '自选', 'Tự chọn', 'เลือกเอง', 'Выбрано самостоятельно', MN_TICKET_SELFPICK_MORE);
  ctx.fillStyle = '#8A8371';
  ctx.font = "600 15px 'Pretendard', -apple-system, sans-serif";
  ctx.textAlign = 'center';
  ctx.fillText(`${dateStr}  ·  ${selfPick}`, W / 2, bandH + 210);

  // 2026-07-31 디자인팀 반영 가이드: 스캔 가능해 보이는 바코드 장식 삭제 — 모노스페이스
  // "Ticket ID" 코드 한 줄로 교체. 실물 바코드보다 "이건 가짜 티켓"이라는 신호가 더 잘
  // 읽힌다는 검수 의견 반영. 번호 조합에서 결정론적으로 뽑아서(진짜 랜덤이 아님) 같은 번호로
  // 다시 저장해도 항상 같은 ID가 나옴(barcodeSeed와 같은 패턴).
  const barcodeSeed = mainNums.reduce((a, b) => a + b, specialNum);
  const ticketSerial = String(10000 + ((barcodeSeed * 7919) % 90000)).slice(0, 5);
  const ticketId = `Ticket ID: KR-${dateStr.replace(/-/g, '')}-${ticketSerial}`;
  ctx.fillStyle = '#8A8371';
  ctx.font = "500 15px 'Menlo', 'Consolas', monospace";
  ctx.textAlign = 'center';
  ctx.fillText(ticketId, W / 2, bandH + 256);

  // 가상 티켓 배지 — 2026-07-31 디자인팀 반영 가이드: "실제 구매 아님" 경고 성격은 다른
  // 카드의 참고용 배지와 달리 그대로 빨간 톤 유지(의도적) — 대신 알약 배지가 아니라 카드 폭
  // 전체 밴드로 통일해서 1~4번 카드와 같은 프레임 언어로 맞춤.
  const disclaimer = pickLang('재미로 만든 가상 티켓 · 실제 구매 아님', 'Fun mock ticket · not a real purchase', '仅供娱乐的虚拟彩票 · 非真实购买', 'Vé số ảo cho vui · không phải giao dịch mua thật', 'ตั๋วจำลองเพื่อความบันเทิง · ไม่ใช่การซื้อจริง', 'Шуточный билет для развлечения · не настоящая покупка', MN_TICKET_DISCLAIMER_MORE);
  const bannerX = 14, bannerW = W - 28, bannerY0 = H - 56, bannerH = 40;
  ctx.beginPath();
  ctx.fillStyle = '#FDECEC';
  ctx.roundRect(bannerX, bannerY0, bannerW, bannerH, 10);
  ctx.fill();
  ctx.fillStyle = '#C0392B';
  ctx.textAlign = 'center';
  fitFontSize(ctx, disclaimer, 700, 15, 11, bannerW - 32);
  ctx.fillText(disclaimer, W / 2, bannerY0 + bannerH / 2 + 1);

  openAnnotateOverlay(canvas, 'chamtax-my-ticket.png');
}

