function toggleJackpotCalc(){
  const box = document.getElementById('jackpot-calc-box');
  const isShowing = box.classList.toggle('show');
  updateJcTapLabel();
  if (isShowing) refreshJackpotDrawerIfOpen();
}

// 홈 화면 계산기는 일시불(lump sum) 기준으로만 계산함 — 연금(annuity) 세금은 30년에 걸쳐
// 매년 다른 세율 구간이 적용되는 완전히 별도의 계산이라 여기에 중복으로 넣지 않고,
// 이미 만들어둔 확률체감 페이지의 잭팟 계산기(연금 단계 포함)로 안내만 함
function toggleTaxTermInfo(){
  toggleInlineTermBox('tax-term-box');
}

// 홈 화면 히어로 결과뿐 아니라, 확률체감 탭 잭팟 계산기와 국가비교 화면의 세부내역 아래에도
// 같은 "탭하면 용어 설명이 펼쳐지는" 박스를 재사용함 — id만 다르게 받아서 어디서든 토글 가능
function toggleInlineTermBox(id){
  const box = document.getElementById(id);
  if (!box) return;
  box.style.display = box.style.display === 'none' ? 'block' : 'none';
}

function goToAnnuityInfo(){
  go('odds');
  const box = document.getElementById('jackpot-calc-box');
  if (!box.classList.contains('show')) toggleJackpotCalc();
  setTimeout(() => {
    document.querySelector('.prize-card.jackpot').scrollIntoView({ behavior: 'smooth', block: 'center' });
  }, 400);
}

// 홈 화면 결과 카드 안에 있는 "연금 선택 시 차이점 확인하기" 버튼 전용 — goToAnnuityInfo()처럼
// 확률체감 탭으로 이동하지 않고, 같은 홈 화면 안에 이미 있는 연금 아코디언만 펼치고 스크롤함
// (2026-07-29, 사용자 피드백으로 발견: 버튼 바로 위에 있는 아코디언을 놔두고 엉뚱하게 다른
// 탭의 잭팟 계산기로 이동하고 있었음)
function openHomeAnnuityDetail(){
  const target = document.getElementById('home-annuity-detail');
  if (!target) return;
  target.open = true;
  target.scrollIntoView({ behavior: 'smooth', block: 'center' });
}

// 스크롤하면서 각 섹션이 살짝 떠오르며 나타나는 효과. reduced-motion 환경에서는 CSS가 즉시 보이게 처리함
let _revealObserver = null;
function setupRevealAnimation(){
  const activeView = document.querySelector('.view.on');
  if (!activeView) return;
  const targets = activeView.querySelectorAll(':scope > .hero, :scope > .panel, :scope > .input-card, :scope > .explore-section, :scope > details, :scope > .legal-section, :scope > form');
  if (!_revealObserver){
    _revealObserver = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting){
          entry.target.classList.add('is-in');
          animateBarsIn(entry.target);
          _revealObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.08, rootMargin: '0px 0px -40px 0px' });
  }
  targets.forEach(el => {
    if (el.classList.contains('is-in') || el.classList.contains('reveal-up')) return;
    el.classList.add('reveal-up');
    _revealObserver.observe(el);
  });
}

// 확률 막대그래프(odds.barPowerball 등)가 화면에 처음 들어올 때 고정폭으로 뚝 나타나지 않고
// 0에서 실제 길이까지 부드럽게 채워지도록 함.
// 예전엔 "style.width를 0%로 리셋했다가 목표값으로 되돌려서 CSS transition이 걸리게 하는" 방식을
// 썼는데(reflow를 강제로 끼워넣는 흔한 트릭 포함해서 시도해봐도), 리셋과 복원이 브라우저가 실제
// 페인트하는 시점 전에 같은 프레임으로 묶여버려서 0% 상태가 화면에 한 번도 그려지지 않고 바로
// 완성 폭으로 뚝 나타나는 문제가 있었음(사용자가 "애니메이션이 사라진 것 같다"고 직접 지적,
// Playwright로 재현 확인) — style 값 전후 비교에 의존하는 CSS transition 대신, Web Animations
// API(Element.animate)로 0%→목표값 구간을 직접 지정하면 이전 페인트 상태와 무관하게 항상
// 재생됨. fill 옵션을 안 써서 애니메이션이 끝나면 원래 inline style(목표값)에 그대로 되돌아감
function animateBarsIn(container){
  const bars = container.querySelectorAll('.bar-fill');
  bars.forEach(bar => {
    const target = bar.style.width;
    if (!target || typeof bar.animate !== 'function') return;
    bar.animate([{ width: '0%' }, { width: target }], { duration: 900, easing: 'cubic-bezier(0.16,1,0.3,1)' });
    const icon = bar.closest('.bar-row')?.querySelector('.bar-icon');
    if (icon) {
      icon.classList.remove('bar-icon-pop');
      void icon.offsetWidth;
      icon.style.animationDelay = '0.75s';
      icon.classList.add('bar-icon-pop');
    }
  });
}

// 입력창·슬라이더는 메인 결과 카드보다 화면 아래쪽에 있어서, 모바일에서 스크롤해서 금액을
// 바꾸면 결과가 바뀌는 게 화면 밖이라 안 보임(사용자가 직접 지적) — 메인 결과 카드가 뷰포트
// 밖으로 나갔을 때만 하단에 작은 배지로 지금 값을 계속 보여줌. MutationObserver로
// home-final-amt 텍스트를 그대로 미러링해서, formatWon() 결과를 쓰는 기존 갱신 코드
// 여러 곳(연금 뷰 제외 계산 관련 전부)을 하나도 안 건드려도 값이 항상 같이 갱신됨
let _stickyResultObserver = null;
function setupStickyResultBadge(){
  const target = document.getElementById('home-final-amt');
  // 결과 카드 밑에 입력창·슬라이더·세금 상세까지가 "관련 구간"이고, 그 밑 탐색 카드부터는
  // 배지랑 상관없는 콘텐츠임 — 이 구간을 완전히 지나쳐 스크롤하면(잭팟 이력·탐색 카드 등이
  // 보일 때) 배지가 그 위에 계속 떠서 글자를 가리는 문제가 있었음(사용자가 스크린샷으로 지적) —
  // "결과 더 자세히 보기"(#home-detail-toggle)가 화면 위로 완전히 넘어가면 배지도 같이 숨김.
  // 2026-07-30: 예전엔 .calc-detail-toggle 클래스로 첫 매치를 찾았는데, 연금 아코디언
  // 병합 전엔 우연히 그게 이 결과 구간의 끝이었을 뿐 — 다른 .calc-detail-toggle(예: 세금
  // 계산 기준 자세히 설정)이 이후 추가되며 querySelector가 엉뚱한 걸 집을 위험이 있어
  // 전용 id로 명시함
  const zoneEnd = document.getElementById('home-detail-toggle');
  const badge = document.getElementById('sticky-result-badge');
  const amtEl = document.getElementById('sticky-result-amt');
  if (!target || !badge || !amtEl || badge.dataset.bound) return;
  badge.dataset.bound = '1';

  let resultOutOfView = false;
  let pastRelevantZone = false;
  // 2026-07-31: 결과를 한 번 본 뒤 "입력값 고치려고 위로 다시 스크롤"하면 배지가 안 떠서
  // 수정하는 동안 지금 결과가 뭐였는지 안 보인다는 지적(사용자가 직접 확인) — 아래 top<0 조건
  // 하나만으로는 "결과를 아직 한 번도 못 본 상태(위쪽)"와 "이미 본 결과를 고치러 다시 올라간
  // 상태(역시 위쪽)"를 구분 못 해서 생긴 문제. 결과가 한 번이라도 화면에 걸쳤으면
  // hasSeenResult를 계속 true로 남겨서, 그 뒤로는 위/아래 어느 방향으로 벗어나도 배지가 뜨게 함.
  let hasSeenResult = false;
  const updateVisibility = () => {
    const isHomeActive = document.getElementById('view-home').classList.contains('on');
    badge.classList.toggle('is-visible', isHomeActive && resultOutOfView && !pastRelevantZone);
  };

  _stickyResultObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.target === target) {
        if (entry.isIntersecting) hasSeenResult = true;
        // !isIntersecting만 보면 "아직 결과까지 스크롤 안 내려간 상태"(예: 맨 위 "나는 어떤
        // 경우일까요?" 섹션)도 "화면 밖"으로 잡혀서, 결과를 한 번도 본 적 없는데 배지부터 뜨는
        // 문제가 있었음(2026-07-24, 320px 실기기 스크린샷으로 발견 — 배지가 realAbroadSelect
        // 드롭다운을 완전히 가려서 클릭도 안 됐음). top이 0보다 작을 때(=결과가 화면 위쪽으로
        // 이미 지나감)거나, 이미 한 번은 본 결과라면(hasSeenResult) "지나쳐서 안 보이는 것"으로
        // 간주 — 처음부터 안 내려가서 안 보이는 것과만 구분함
        resultOutOfView = !entry.isIntersecting && (hasSeenResult || entry.boundingClientRect.top < 0);
      } else if (entry.target === zoneEnd) {
        pastRelevantZone = entry.boundingClientRect.bottom < 0;
      }
    });
    updateVisibility();
  }, { threshold: 0 });
  _stickyResultObserver.observe(target);
  if (zoneEnd) _stickyResultObserver.observe(zoneEnd);

  new MutationObserver(() => { amtEl.textContent = target.textContent; }).observe(target, { childList: true, characterData: true, subtree: true });
  amtEl.textContent = target.textContent;
}
function scrollToMainResult(){
  const target = document.getElementById('home-final-amt');
  if (target) target.scrollIntoView({ behavior: 'smooth', block: 'center' });
}

// "궁금해요" 플로팅 버튼(#faqFloatBtn)이 스크롤 없이 화면을 막 열었을 때부터 실제 콘텐츠 위에
// 그대로 겹쳐 보이는 문제(2026-07-25 시각 감사 지적) — 로드 직후엔 숨겨두고, 어느 정도
// 스크롤을 내려야 나타나게 함(styles.css .faq-float-btn.is-visible). go('faq')로 도움말
// 화면 자체에 있을 때 숨기는 기존 .is-hidden 로직과는 별개로 항상 같이 동작함(display:none이
// opacity/pointer-events보다 우선하므로 두 로직이 서로 안 부딪힘)
const FAQ_FLOAT_SCROLL_THRESHOLD = 150;
// 2026-07-25: 로드 직후 안 보이게만 해서는 부족했음 — 사용자가 스크린샷으로 재확인, 스크롤
// 후 자연스럽게 멈춘 위치에서도 이 버튼이 확률체감 탭의 "일시불 대신 연금으로 받으면?" 문구나
// 잭팟 단계별 금액 위에 그대로 얹히는 경우가 있었음. 스크롤 임계값만으로는 "화면에 보일지"는
// 정할 수 있어도 "하필 그 자리에 뭐가 있는지"는 알 수 없음 — document.elementsFromPoint()로
// 버튼이 차지하는 실제 화면 영역 밑에 글자가 있는 텍스트 요소가 있는지 직접 확인해서, 있으면
// 그 순간만 흐리게 비활성화함(버튼 자체를 없애지 않아 스크롤이 멈추면 곧바로 다시 씀 가능)
// 2026-07-30: 이 검사가 원래 "흐리게 할지(is-colliding)" 하나만 판단했는데, 그 안에서
// button/a/summary 같은 실제 컨트롤은 흐림 판정에서 제외해버려서(아래 주석 참고) 그
// 컨트롤 위에서는 pointer-events가 계속 auto로 남아있었음 — 그 결과 이 플로팅 버튼이 뒤에
// 깔린 진짜 버튼/아코디언 제목의 탭을 그대로 가로채는 문제가 있었음(홈 화면 FAQ 카드,
// 오즈 화면 아코디언에서 실제로 재현됨, UX 점검 서브에이전트가 발견). "흐리게 보일지"와
// "탭을 통과시킬지"는 서로 다른 질문이라 분리함 — 컨트롤과 겹칠 땐 흐리게 하진 않되(2026-07-29
// 피드백대로 그대로 유지) 탭은 통과시켜서 밑에 있는 진짜 버튼이 눌리게 함
function faqFloatBtnCollisionState(btn){
  const rect = btn.getBoundingClientRect();
  if (!rect.width || !rect.height) return { overText: false, overControl: false };
  const points = [
    [rect.left + rect.width * 0.5, rect.top + 2],
    [rect.left + rect.width * 0.5, rect.bottom - 2],
    [rect.left + 4, rect.top + rect.height * 0.5],
    [rect.right - 4, rect.top + rect.height * 0.5],
  ];
  let overText = false;
  let overControl = false;
  for (const [x, y] of points) {
    if (x < 0 || y < 0 || x > window.innerWidth || y > window.innerHeight) continue;
    const stack = document.elementsFromPoint(x, y);
    for (const el of stack) {
      if (el === btn || btn.contains(el)) continue;
      // 2026-07-29: "일시불 대신 연금(annuity)으로 받으면?" 아코디언 제목 위에서 이 버튼이
      // 흐려지는 게 거슬린다는 사용자 피드백(스크린샷) — 원래 이 충돌 감지는 "뒤에 깔린 읽을
      // 수 없게 되는 글(문단 등)을 가리지 않게" 하려는 목적인데, 버튼·링크·아코디언 제목
      // (<summary>)처럼 그 자체가 누르는 대상인 컨트롤과 겹치는 것까지 같은 취급을 받고
      // 있었음. 이런 요소는 계속 읽어야 하는 콘텐츠가 아니라 한눈에 훑고 누르는 대상이라
      // 겹쳐도 "글이 가려져서 못 읽음" 문제가 아니므로 흐림 판정에서는 계속 제외하되,
      // overControl로 표시해서 최소한 탭은 통과시킴(바로 아래 updateFaqFloatBtnVisibility 참고)
      if (el.closest('button, a, summary, [role="button"]')) { overControl = true; continue; }
      // 버튼 자신에 도달하기 전에 카드 배경(:before/배경 전용 요소)만 있으면 계속 더 아래(뒤)
      // 요소를 확인 — 실제로 눈에 보이는 글자가 있는 leaf 요소를 만나면 그때 충돌로 판단
      const text = (el.textContent || '').trim();
      if (!text) continue;
      // el 자신이 텍스트를 직접 담은 노드인지(자식 요소가 아니라 텍스트 노드가 바로 있는지) 확인 —
      // 아니면 큰 컨테이너(예: .page 전체)가 우연히 그 지점에 있다고 항상 걸리는 오탐이 생김
      const hasDirectText = Array.from(el.childNodes).some(n => n.nodeType === Node.TEXT_NODE && n.textContent.trim());
      if (hasDirectText) { overText = true; break; }
    }
    if (overText) break;
  }
  return { overText, overControl };
}

function updateFaqFloatBtnVisibility(){
  const wrap = document.getElementById('faqFloatWrap');
  if (!wrap) return;
  const scrolledEnough = window.scrollY > FAQ_FLOAT_SCROLL_THRESHOLD;
  wrap.classList.toggle('is-visible', scrolledEnough);
  if (!scrolledEnough) { wrap.classList.remove('is-colliding', 'is-over-control'); return; }
  const { overText, overControl } = faqFloatBtnCollisionState(wrap);
  wrap.classList.toggle('is-colliding', overText);
  // is-colliding이 이미 pointer-events:none을 주므로, 텍스트와도 겹친 경우엔 굳이 별도
  // 클래스가 필요 없음 — 흐려지진 않지만 탭은 통과시켜야 하는 "컨트롤과만 겹친" 경우에만 부여
  wrap.classList.toggle('is-over-control', overControl && !overText);
}

function setupFaqFloatBtnScrollVisibility(){
  const btn = document.getElementById('faqFloatWrap');
  if (!btn || btn.dataset.scrollBound) return;
  btn.dataset.scrollBound = '1';
  let ticking = false;
  let settleTimer = null;
  // 2026-07-30: 제미나이 검수(12번 항목)가 추천한 "스크롤 중 자동 숨김" 패턴 추가 — 아래로
  // 스크롤할 땐 이 버튼을 잠깐 숨겨서 다른 컨트롤과 겹칠 일 자체를 줄이고(위 is-over-control
  // 방어 코드와 별개로 애초에 안 겹치게), 위로 스크롤하거나 스크롤이 멈추면(기존 settleTimer
  // 재사용) 다시 보이게 함. 아주 작은 스크롤 흔들림(모멘텀 스크롤 끝자락 등)에 매번
  // 반응하면 버튼이 깜빡여서, 최소 이동량(SCROLL_HIDE_DELTA)을 넘을 때만 방향을 갱신함
  let lastScrollY = window.scrollY;
  const SCROLL_HIDE_DELTA = 4;
  // 스크롤 중엔 보이기/숨기기(임계값 기준)만 매 프레임 즉시 반영하고, "지금 밑에 글자가
  // 있는지" 충돌 검사(faqFloatBtnCollidesWithText, 무거운 elementsFromPoint 호출)는 스크롤이
  // 실제로 멈춘 뒤에만 한 번 함 — 원래는 이것도 매 프레임 같이 돌렸는데, 스크롤 중에 버튼
  // 밑을 스쳐가는 글자마다 옅어졌다 진해졌다 하며 깜빡이는 문제(2026-07-25 지적)로 분리함
  const updateShowHideOnly = () => {
    const currentY = window.scrollY;
    const delta = currentY - lastScrollY;
    if (Math.abs(delta) > SCROLL_HIDE_DELTA) {
      btn.classList.toggle('is-scroll-hidden', delta > 0); // 아래로 스크롤 중이면 숨김
      lastScrollY = currentY;
    }
    const scrolledEnough = currentY > FAQ_FLOAT_SCROLL_THRESHOLD;
    btn.classList.toggle('is-visible', scrolledEnough);
    if (!scrolledEnough) btn.classList.remove('is-colliding');
  };
  const onScroll = () => {
    if (!ticking) {
      ticking = true;
      requestAnimationFrame(() => { ticking = false; updateShowHideOnly(); });
    }
    clearTimeout(settleTimer);
    settleTimer = setTimeout(() => {
      // 스크롤이 멈추면 마지막 방향과 무관하게 항상 다시 보이게 함(기존 충돌 재검사와 같은 타이밍)
      btn.classList.remove('is-scroll-hidden');
      updateFaqFloatBtnVisibility();
    }, 150);
  };
  window.addEventListener('scroll', onScroll, { passive: true });
  // 잭팟 계산 드로어(details/summary)나 "일시불 대신 연금으로" 같은 아코디언을 열고 닫으면
  // 스크롤은 그대로인데 그 아래 콘텐츠 높이가 바뀌어서 겹침 여부가 달라질 수 있음. 이건 스크롤처럼
  // 연속으로 일어나는 이벤트가 아니라서 매번 전체 검사(충돌 포함)를 그대로 해도 깜빡임 문제가 없음.
  // 'toggle' 이벤트는 버블링을 안 해서 document에 capture:true로 걸어야 모든 <details>를
  // 한 번에 잡을 수 있음(요소마다 따로 리스너를 안 달아도 됨)
  document.addEventListener('toggle', updateFaqFloatBtnVisibility, true);
  updateFaqFloatBtnVisibility();
}

// 확률체감 탭의 실수령액 랭킹/물가보정 랭킹 위젯은 sharedCountry(세금 기준)를 따라 문구가
// 바뀌는데, 정작 이 탭 안에는 기준을 바꿀 방법이 없어서 홈 화면까지 되돌아가야 했음(2026-07-24
// 사용자 지적으로 발견). 처음엔 go('home')으로 탭 자체를 전환하는 goToHomeCountryToggle()을
// 썼었는데, 그러면 보고 있던 랭킹 목록·스크롤 위치를 잃고 되돌아오기 불편하다는 피드백이 또
// 있어서(openFaqSearchFloat()과 같은 문제 클래스) 탭 전환 없는 팝오버로 교체함 — 아래 참고
