// #homeCountryToggle DOM 노드를 통째로 옮겨서 재사용(21개 국가 버튼 마크업/onclick 배선을
// 오버레이용으로 중복 생성하지 않기 위함) — 닫을 때 #homeCountryTogglePlaceholder 자리로
// 되돌려놓아야 홈 화면에서도 다시 정상적으로 보임(closeTaxBasisOverlay 참고)
function openTaxBasisOverlay(){
  const overlay = document.getElementById('taxBasisOverlay');
  const body = document.getElementById('taxBasisOverlayBody');
  const toggle = document.getElementById('homeCountryToggle');
  const titleEl = document.getElementById('taxBasisOverlayTitle');
  if (!overlay || !body || !toggle) return;
  if (titleEl) titleEl.textContent = pickLang('🔧 세금 기준 바꾸기', '🔧 Change tax basis', '🔧 更改税收基准', '🔧 Đổi cơ sở tính thuế', '🔧 เปลี่ยนเกณฑ์ภาษี', '🔧 Изменить налоговую базу', TAX_BASIS_OVERLAY_TITLE_MORE);
  body.appendChild(toggle);
  overlay.classList.add('show');
}

function closeTaxBasisOverlay(){
  const overlay = document.getElementById('taxBasisOverlay');
  const toggle = document.getElementById('homeCountryToggle');
  const placeholder = document.getElementById('homeCountryTogglePlaceholder');
  if (overlay) overlay.classList.remove('show');
  if (toggle && placeholder && placeholder.parentNode) placeholder.parentNode.insertBefore(toggle, placeholder);
}

// ===== 국가/통화 select 3개(#homeCountrySelect/#homeCurrencySelect/#compareCurrencySelect) 공용
// 검색형 바텀시트(2026-07-30) =====
// 외부 UX 검수가 21개짜리 네이티브 <select>를 모바일 OS 피커로 스크롤하는 게 40-60대 타깃에게
// 번거롭다고 지적해서 추가. 진짜 <select>는 그대로 두고(index.html의 .select-sheet-native 참고 —
// onchange 배선·값 읽기 코드가 이미 사이트 곳곳에 있어서 절대 안 건드림), 그 위에 얹은 커스텀
// 트리거(.select-sheet-trigger)를 누르면 이 시트가 뜸. 항목을 고르면 select.value를 실제로
// 설정하고 진짜 'change' 이벤트를 dispatch함(직접 setHomeCountry()/setSharedInputCurrency()를
// 호출하지 않는 이유: 나중에 이 select에 또 다른 change 리스너가 추가돼도 이 시트 경로만 빠지는
// 회귀를 원천 차단하기 위함 — 네이티브 select로 고를 때와 완전히 같은 경로를 타야 함).

// 통화 select(homeCurrencySelect/compareCurrencySelect)는 옵션 코드 자체가 이미 통용되는 이름이라
// 별도 번역이 필요 없지만(ISO 코드), "베트남"이라고 쳐도 VND를 찾을 수 있게 하려고 같은 나라의
// 국가 select 검색어를 재사용함(새 i18n 키를 추가하지 않고 기존 #homeCountryToggle 버튼의
// 이미 번역된 텍스트를 그대로 읽어옴)
const CURRENCY_TO_COUNTRY_FOR_SEARCH = {
  KRW:'kr', USD:'us', CNY:'cn', INR:'in', VND:'vn', IDR:'id', PHP:'ph', THB:'th', JPY:'jp', RUB:'ru',
  NPR:'np', LKR:'lk', UZS:'uz', KZT:'kz', KGS:'kg', MMK:'mm', BDT:'bd', PKR:'pk', KHR:'kh', MNT:'mn', LAK:'la',
};

// #homeCountryToggle 버튼들(21개 국가 + 기타)은 openTaxBasisOverlay()가 팝오버 안으로 옮겨도
// id는 그대로라 어디에 있든 이 셀렉터로 찾아짐 — 이미 applyTranslations()가 현재 언어로 계속
// 갱신해주는 살아있는 DOM 텍스트를 그대로 검색어로 재사용(새 자료구조·새 번역 유지보수 없음)
function countrySearchTextFor(countryCode){
  const btn = document.querySelector('#homeCountryToggle .country-toggle-btn[data-country="' + countryCode + '"]');
  return btn ? btn.textContent.trim() : '';
}

function currencySearchTextFor(currencyCode){
  const countryCode = CURRENCY_TO_COUNTRY_FOR_SEARCH[currencyCode];
  return countryCode ? countrySearchTextFor(countryCode) : '';
}

// 트리거 버튼에 보이는 라벨은 항상 실제 select의 현재 선택된 <option> 텍스트를 그대로 씀(국가는
// 코드만, 통화는 국기+코드 — 새 표기 규칙을 만들지 않고 이미 있는 <option> 텍스트를 그대로 재사용).
// setHomeCountry()/setSharedInputCurrency()가 select.value를 직접 바꾸는 경로(이 시트를 거치지
// 않고 #homeCountryToggle 버튼을 직접 눌렀거나 ?country= 쿼리로 초기화된 경우 등)에도 라벨이
// 어긋나지 않도록, 그 두 함수 끝에서도 이 함수를 호출함
function syncSelectSheetTrigger(selectId){
  const select = document.getElementById(selectId);
  const trigger = document.getElementById(selectId + 'Trigger');
  if (!select || !trigger) return;
  const label = trigger.querySelector('.select-sheet-trigger-label');
  const opt = select.options[select.selectedIndex];
  if (label) label.textContent = opt ? opt.textContent : '';
}

function initSelectSheetTriggers(){
  ['homeCountrySelect', 'homeCurrencySelect', 'compareCurrencySelect'].forEach(syncSelectSheetTrigger);
}
document.addEventListener('DOMContentLoaded', initSelectSheetTriggers);

let selectSheetTargetId = null;

function openSelectSheet(selectId){
  const select = document.getElementById(selectId);
  const overlay = document.getElementById('selectSheetOverlay');
  const listEl = document.getElementById('selectSheetList');
  const searchEl = document.getElementById('selectSheetSearch');
  const titleEl = document.getElementById('selectSheetTitle');
  if (!select || !overlay || !listEl || !searchEl) return;
  selectSheetTargetId = selectId;
  // 시트 제목은 이 select 옆에 이미 붙어있는 <label>(국가/통화, 이미 26개 언어로 번역돼있음)을
  // 그대로 재사용 — 새 타이틀 문구를 따로 만들 필요 없음
  const labelEl = document.querySelector('label[for="' + selectId + '"]');
  if (titleEl) titleEl.textContent = labelEl ? labelEl.textContent.trim() : '';
  const isCountrySelect = selectId === 'homeCountrySelect';
  listEl.innerHTML = '';
  Array.from(select.options).forEach(opt => {
    const row = document.createElement('button');
    row.type = 'button';
    row.className = 'select-sheet-item' + (opt.value === select.value ? ' active' : '');
    row.setAttribute('role', 'option');
    row.setAttribute('aria-selected', opt.value === select.value ? 'true' : 'false');
    // 화면엔 기존 <option> 텍스트를 그대로만 보여줌(국가는 코드만, 통화는 국기+코드 — 요구사항대로
    // 새 시각 정보를 추가하지 않음). 검색은 코드/값 + 번역된 국가명까지 포함해서 넓게 매칭함
    row.textContent = opt.textContent;
    const searchExtra = isCountrySelect ? countrySearchTextFor(opt.value) : currencySearchTextFor(opt.value);
    row.dataset.search = (opt.textContent + ' ' + opt.value + ' ' + searchExtra).toLowerCase();
    row.onclick = () => pickSelectSheetItem(opt.value);
    listEl.appendChild(row);
  });
  searchEl.value = '';
  filterSelectSheet();
  overlay.classList.add('show');
  // 시트가 슬라이드업하는 도중 바로 포커스를 주면 스크롤 점프가 겹쳐 보일 수 있어 애니메이션
  // 시간(0.22s)만큼 살짝 늦춤 — faqSearch 포커스와 같은 타이밍 관례(openFaqSearchFloat 참고)
  setTimeout(() => searchEl.focus(), 50);
}

function closeSelectSheet(){
  const overlay = document.getElementById('selectSheetOverlay');
  if (overlay) overlay.classList.remove('show');
  selectSheetTargetId = null;
}

function filterSelectSheet(){
  const listEl = document.getElementById('selectSheetList');
  const searchEl = document.getElementById('selectSheetSearch');
  const noResultEl = document.getElementById('selectSheetNoResult');
  if (!listEl || !searchEl) return;
  const q = searchEl.value.trim().toLowerCase();
  let visibleCount = 0;
  Array.from(listEl.children).forEach(row => {
    const match = !q || row.dataset.search.includes(q);
    row.style.display = match ? '' : 'none';
    if (match) visibleCount++;
  });
  if (noResultEl) noResultEl.style.display = visibleCount === 0 ? 'block' : 'none';
}

// 선택 확정 — 진짜 select의 값을 바꾸고 실제 change 이벤트를 dispatch해서 기존
// onchange="setHomeCountry(this.value)"/"setSharedInputCurrency(this.value, true)" 배선이
// 네이티브 select로 직접 고를 때와 완전히 같은 경로로 호출되게 함(핵심 요구사항 — 이 시트만의
// 별도 상태 갱신 로직을 만들지 않음)
function pickSelectSheetItem(value){
  const select = document.getElementById(selectSheetTargetId);
  if (!select) { closeSelectSheet(); return; }
  select.value = value;
  select.dispatchEvent(new Event('change', { bubbles: true }));
  closeSelectSheet();
}

// 어느 화면에서든 뜨는 #faqFloatBtn용 — go('faq')로 실제 탭을 전환하면 사용자가 보던 화면
// (입력값·스크롤 위치)에서 완전히 벗어나고, 닫은 뒤 다시 보기 힘들다는 피드백이 있었음. 그래서
// 탭 전환 없이 #view-faq를 현재 화면 위에 덮어씌우는 오버레이로만 띄움 — 닫으면 클래스만
// 제거되고 원래 화면은 그대로 밑에 남아있음
function openFaqSearchFloat(){
  const faqView = document.getElementById('view-faq');
  if (!faqView) return;
  filterFaq(); // 오버레이로 뜨기 전에 현재 세금 기준 기준으로 한 번 새로 걸러줌
  faqView.classList.add('faq-overlay-mode');
  setTimeout(() => {
    const searchInput = document.getElementById('faqSearch');
    if (!searchInput) return;
    searchInput.scrollIntoView({ behavior: 'smooth', block: 'start' });
    searchInput.focus();
  }, 50);
}

function closeFaqOverlay(){
  const faqView = document.getElementById('view-faq');
  if (faqView) faqView.classList.remove('faq-overlay-mode');
}

document.addEventListener('keydown', e => {
  if (e.key === 'Escape') { closeFaqOverlay(); closeTaxBasisOverlay(); closeSelectSheet(); }
});

// "궁금해요" 플로팅 버튼 자체가 거슬리는 사람을 위한 영구 닫기(2026-07-27) — 세션이 아니라
// localStorage에 저장해서 다음 방문에도 계속 숨겨짐(홈 FAQ 미리보기 닫기와 같은 패턴)
const FAQ_FLOAT_BTN_DISMISS_KEY = 'chamtaxFaqFloatBtnDismissed';

function initFaqFloatBtnDismiss(){
  const wrap = document.getElementById('faqFloatWrap');
  if (!wrap) return;
  let dismissed = false;
  try { dismissed = localStorage.getItem(FAQ_FLOAT_BTN_DISMISS_KEY) === '1'; } catch (e) {}
  if (dismissed) wrap.style.display = 'none';
}

function dismissFaqFloatBtn(event){
  if (event) event.stopPropagation();
  const wrap = document.getElementById('faqFloatWrap');
  if (wrap) wrap.style.display = 'none';
  try { localStorage.setItem(FAQ_FLOAT_BTN_DISMISS_KEY, '1'); } catch (e) {}
}

document.addEventListener('DOMContentLoaded', initFaqFloatBtnDismiss);

// ===== "궁금해요" 검색을 홈/비교/확률체감 탭까지 확장 =====
// 예전엔 filterFaq()가 FAQ 화면 안의 항목만 걸러서, 정작 답이 홈(계산기)이나 확률체감 탭에
// 있는 질문(예: "확률", "잭팟 얼마")은 검색해도 못 찾았음. 언어별로 따로 매핑을 하드코딩하는
// 대신, 이미 i18n이 적용되어 화면에 실제로 렌더링된 제목/라벨 텍스트를 그대로 검색 대상으로
// 삼아서 22개 언어 어디서든 별도 유지보수 없이 동일하게 동작하게 함
let crossTabSearchIndex = null;

function buildCrossTabSearchIndex(){
  const idx = [];
  const selector = [
    '#view-home h1', '#view-home h2', '#view-home .panel-title', '#view-home .explore-label', '#view-home .trust-name',
    '#view-compare h2', '#view-compare .panel-title',
    '#view-odds h2', '#view-odds .panel-title', '#view-odds .feature-title', '#view-odds summary',
  ].join(', ');
  document.querySelectorAll(selector).forEach(el => {
    const text = el.textContent.trim();
    // 너무 짧은 텍스트(아이콘만 있는 경우 등)나 너무 긴 텍스트(문단급)는 검색 매칭 정확도가
    // 떨어지므로 제외 — 제목/라벨 수준의 길이만 색인 대상으로 삼음
    if (text.length < 2 || text.length > 40) return;
    const view = el.closest('.view');
    if (!view) return;
    idx.push({ el, text: text.toLowerCase(), viewId: view.id.replace('view-', '') });
  });
  return idx;
}

// 언어가 바뀌면 화면 텍스트가 통째로 다시 렌더링되므로, 색인도 다음 검색 시점에 새로 만들도록
// 캐시를 비워둠(setLanguage에서 호출)
function invalidateCrossTabSearchIndex(){ crossTabSearchIndex = null; }

// 검색어가 다른 탭의 제목/라벨과 매칭되면 그 탭으로 이동해서 스크롤+하이라이트, 매칭되면 true 반환
function tryCrossTabSearchJump(query){
  const q = (query || '').trim().toLowerCase();
  if (q.length < 2) return false;
  if (!crossTabSearchIndex) crossTabSearchIndex = buildCrossTabSearchIndex();
  const hit = crossTabSearchIndex.find(t => t.text.includes(q) || q.includes(t.text));
  if (!hit) return false;
  closeFaqOverlay();
  go(hit.viewId);
  // go()가 화면을 막 그린 직후라 레이아웃이 아직 자리 잡기 전일 수 있어 한 틱 늦춰서 스크롤함
  setTimeout(() => {
    hit.el.scrollIntoView({ behavior: 'smooth', block: 'center' });
    hit.el.classList.add('search-jump-highlight');
    setTimeout(() => hit.el.classList.remove('search-jump-highlight'), 1600);
  }, 200);
  return true;
}

// 타이핑할 때마다(oninput) 화면이 다른 탭으로 훅훅 튀면 오히려 산만해지므로, 실시간 입력은
// 기존처럼 FAQ 안에서만 필터링하고 — Enter를 누르거나 음성 인식 결과가 확정된, "질문을 다
// 마쳤다"고 볼 수 있는 시점에만 다른 탭 이동을 시도함
function handleFaqSearchSubmit(){
  const input = document.getElementById('faqSearch');
  if (!input) return;
  if (tryCrossTabSearchJump(input.value)) return;
  filterFaq(); // 다른 탭에 해당하는 답이 없으면 기존처럼 FAQ 안에서 검색 결과를 보여줌
}

// ===== 음성으로 검색(Web Speech API) =====
// iOS Safari는 이 글을 쓰는 시점(2026-07) 기준 SpeechRecognition을 지원하지 않음 — 지원 안 하는
// 브라우저에서는 버튼 자체를 숨겨서, 눌러도 반응 없는 버튼을 보여주는 상황을 피함
const SpeechRecognitionCtor = window.SpeechRecognition || window.webkitSpeechRecognition || null;
let faqVoiceRecognition = null;

// 사이트가 지원하는 언어 코드 → 음성 인식용 BCP-47 로케일. 브라우저가 이 힌트로 발음을
// 더 정확히 알아들음(값이 없는 언어는 각 브라우저가 자동 감지하는 기본값에 맡김)
const FAQ_VOICE_LANG_MAP = {
  ko: 'ko-KR', en: 'en-US', zh: 'zh-CN', vi: 'vi-VN', th: 'th-TH', ru: 'ru-RU',
  km: 'km-KH', ne: 'ne-NP', id: 'id-ID', my: 'my-MM', si: 'si-LK', uz: 'uz-UZ',
  mn: 'mn-MN', kk: 'kk-KZ', ky: 'ky-KG', ur: 'ur-PK', bn: 'bn-BD', lo: 'lo-LA',
  ja: 'ja-JP', ar: 'ar-SA', hi: 'hi-IN', fr: 'fr-FR', tl: 'fil-PH',
  // 2026-07-30: 음성으로 읽어주기(TTS) 추가하면서 이 지도를 그것에도 재사용하다가 빠진 3개 언어
  // 발견(원래도 음성 검색에서 이 3개는 'ko-KR'로 잘못 폴백되고 있었음) — 같이 채움
  pt: 'pt-PT', es: 'es-ES', uk: 'uk-UA', tet: 'pt-PT',
};

function initFaqVoiceButton(){
  const btn = document.getElementById('faqVoiceBtn');
  if (!btn) return;
  if (!SpeechRecognitionCtor) { btn.style.display = 'none'; return; }
  btn.style.display = '';
}

function startFaqVoiceSearch(){
  if (!SpeechRecognitionCtor) return;
  const btn = document.getElementById('faqVoiceBtn');
  const input = document.getElementById('faqSearch');
  if (!input) return;

  // 이미 듣고 있는 중에 다시 누르면 중지(토글) — 사용자가 실수로 계속 눌러도 안전
  if (faqVoiceRecognition) { faqVoiceRecognition.stop(); return; }

  faqVoiceRecognition = new SpeechRecognitionCtor();
  faqVoiceRecognition.lang = FAQ_VOICE_LANG_MAP[currentLang] || 'ko-KR';
  faqVoiceRecognition.interimResults = true;
  faqVoiceRecognition.maxAlternatives = 1;

  faqVoiceRecognition.onstart = () => { if (btn) btn.classList.add('listening'); };
  faqVoiceRecognition.onresult = (e) => {
    const transcript = Array.from(e.results).map(r => r[0].transcript).join('');
    input.value = transcript;
    filterFaq(); // 말하는 중에도 FAQ 안 실시간 필터링은 계속 보여줌
    const lastResult = e.results[e.results.length - 1];
    if (lastResult && lastResult.isFinal) handleFaqSearchSubmit(); // 문장이 끝나면 다른 탭 이동도 시도
  };
  faqVoiceRecognition.onerror = () => { if (btn) btn.classList.remove('listening'); faqVoiceRecognition = null; };
  faqVoiceRecognition.onend = () => { if (btn) btn.classList.remove('listening'); faqVoiceRecognition = null; };

  try { faqVoiceRecognition.start(); } catch (e) { /* 이미 시작된 세션 등 — 조용히 무시 */ }
}

document.addEventListener('DOMContentLoaded', initFaqVoiceButton);

// 홈 화면 금액 입력칸(일시불/연금액)에도 같은 음성 인식 버튼을 붙임(2026-07-27, "말로 금액을
// 입력하고 싶다"는 요청) — FAQ 검색과 똑같이 SpeechRecognitionCtor/FAQ_VOICE_LANG_MAP을 재사용함
let amountVoiceRecognition = null;

function initAmountVoiceButtons(){
  ['homeAmountVoiceBtn', 'homeAnnouncedVoiceBtn'].forEach(id => {
    const btn = document.getElementById(id);
    if (!btn) return;
    if (!SpeechRecognitionCtor) { btn.style.display = 'none'; return; }
    btn.style.display = '';
  });
}

// ===== 음성으로 읽어주기(Web Speech API TTS, 2026-07-30) =====
// "사이트에 음성 읽어주기 있지 않나?" 확인 요청 → 없었음(위 두 섹션은 전부 "말하면 받아쓰는"
// 음성 입력이지 "글을 읽어주는" TTS가 아니었음) — 핵심 결과(홈 실수령액, 비교 탭 1위 카드)와
// FAQ 답변에만 추가함. 이미 화면에 pickLang()/i18n으로 렌더링된 텍스트를 그대로 읽으므로
// 이 기능 자체를 위한 새 번역 문장이 따로 필요 없음(버튼 라벨만 예외)
const speechSynthesisSupported = typeof window !== 'undefined' && 'speechSynthesis' in window;
let activeTtsUtterance = null;
let activeTtsBtn = null;

function stopReadingAloud(){
  if (speechSynthesisSupported) window.speechSynthesis.cancel();
  if (activeTtsBtn) activeTtsBtn.classList.remove('speaking');
  activeTtsUtterance = null;
  activeTtsBtn = null;
}

// getText: 문자열 또는 "지금 화면에 보이는 텍스트를 즉석에서 모아주는 함수" — 버튼을 누르는
// 시점의 최신 언어/결과값을 읽어야 하므로, 미리 문자열로 굳혀두지 않고 클릭 때마다 새로 계산함
function toggleReadAloud(getText, btn){
  if (!speechSynthesisSupported) return;
  const wasSameBtn = activeTtsBtn === btn;
  if (activeTtsUtterance) { stopReadingAloud(); if (wasSameBtn) return; }
  const text = (typeof getText === 'function' ? getText() : (getText || '')).trim();
  if (!text) return;
  const utter = new SpeechSynthesisUtterance(text);
  utter.lang = FAQ_VOICE_LANG_MAP[currentLang] || 'ko-KR';
  utter.rate = 0.95;
  utter.onend = stopReadingAloud;
  utter.onerror = stopReadingAloud;
  activeTtsUtterance = utter;
  activeTtsBtn = btn || null;
  if (btn) btn.classList.add('speaking');
  window.speechSynthesis.speak(utter);
}

// 홈 결과 카드("일시불 예상 실수령액" 헤드라인) 읽어주기 — 라벨·금액·계산 기준을 화면에
// 보이는 그대로 이어붙여 읽음(새 문구를 따로 만들지 않고 이미 렌더링된 DOM 텍스트 재사용)
function readHomeResultAloud(btn){
  toggleReadAloud(() => {
    const parts = [
      document.querySelector('#view-home .result-hero-label')?.textContent,
      document.getElementById('home-final-amt')?.textContent,
      document.getElementById('home-final-basis-mini')?.textContent,
    ];
    return parts.filter(Boolean).join('. ');
  }, btn);
}

function initResultTtsButtons(){
  document.querySelectorAll('.tts-btn').forEach(btn => {
    if (!speechSynthesisSupported) { btn.style.display = 'none'; return; }
    btn.style.display = '';
  });
}
document.addEventListener('DOMContentLoaded', initResultTtsButtons);

// FAQ 답변마다 "읽어주기" 버튼을 붙임 — HTML에 30개 가까이 똑같은 버튼을 반복해서 적어두는
// 대신, 이미 있는 .faq-a 뒤에 한 번만 동적으로 삽입함. data-i18n-html로 언어가 바뀔 때마다
// .faq-a의 innerHTML 자체는 새로 그려지지만, 이 버튼은 .faq-a의 형제(다음 요소)라 그때마다
// 같이 지워지지 않음
function initFaqTtsButtons(){
  if (!speechSynthesisSupported) return;
  document.querySelectorAll('.faq-item > .faq-a').forEach(ans => {
    if (ans.nextElementSibling && ans.nextElementSibling.classList.contains('faq-tts-btn')) return;
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'annuity-info-link tts-btn faq-tts-btn';
    btn.setAttribute('data-i18n', 'a11y.readAloudBtn');
    btn.textContent = '🔊 읽어주기';
    // textContent를 쓰면 <br><br>이 그냥 사라져서 문장이 붙어버림(예: "정산돼요.👉 한국") —
    // innerText는 렌더링된 줄바꿈을 개행으로 남겨서 TTS가 문장 사이에 자연스럽게 끊어 읽음
    btn.addEventListener('click', () => toggleReadAloud(() => ans.innerText, btn));
    ans.insertAdjacentElement('afterend', btn);
  });
}
document.addEventListener('DOMContentLoaded', initFaqTtsButtons);

// ===== 음성 인식 금액 파싱(2026-07-27, "오천만원처럼 말해도 되게" 요청) =====
// 입력칸은 항상 "USD 백만 단위"를 기대하는데, 실제로 말할 때는 두 가지 문제가 있었음:
// 1) "오천만원"처럼 한글 숫자 단어(만/억/천 등)로 말하면 아라비아 숫자가 하나도 없어서
//    기존의 "숫자만 남기고 지우기" 방식으로는 빈 문자열이 되어 아무 반응이 없었음
// 2) 원(KRW)이나 각 나라 통화로 말하면, 환전 없이 숫자만 그대로 들어가 전혀 다른 금액이 입력됨
// koreanWordsToNumber()가 한글 숫자 단어(+섞인 아라비아 숫자)를 실제 값으로 환산하고,
// detectSpokenCurrencyRate()가 원/달러 및 사이트가 이미 관리 중인 각국 환율(EXCHANGE_RATE_*)로
// 통화 키워드를 인식해 최종적으로 USD 백만 단위로 환산함. 통화 키워드가 전혀 없으면 기존처럼
// "이미 USD 백만 단위"로 간주해 하위호환을 유지함. 22개 언어 전부의 고유 숫자 읽기 체계까지
// 완벽히 지원하진 못하지만(한글 숫자 단어 파싱은 한국어 전용), 통화 키워드 인식과 million/
// billion/thousand 배율 처리는 모든 언어에 공통 적용됨

const KOR_NUM_DIGIT = { 영:0, 공:0, 일:1, 이:2, 삼:3, 사:4, 오:5, 육:6, 륙:6, 칠:7, 팔:8, 구:9 };
const KOR_NUM_SMALL_UNIT = { 십:10, 백:100, 천:1000 };
const KOR_NUM_BIG_UNIT = { 만:10000, 억:100000000, 조:1000000000000 };

// 한글 숫자 단어(아라비아 숫자와 섞여도 됨, 예: "3억5000만")를 실제 값으로 환산.
// 한글 숫자 관련 글자가 하나도 없으면 null(= 순수 아라비아 숫자만 있다는 뜻이라 기존 방식으로 처리)
function koreanWordsToNumber(text){
  let matched = false;
  let result = 0, section = 0, current = 0, numBuf = '';
  const flushBuf = () => { if (!numBuf) return null; const v = Number(numBuf); numBuf = ''; return v; };
  for (const ch of text) {
    if (ch >= '0' && ch <= '9') { numBuf += ch; continue; }
    if (Object.prototype.hasOwnProperty.call(KOR_NUM_DIGIT, ch)) {
      const bufVal = flushBuf();
      current = bufVal !== null ? bufVal : KOR_NUM_DIGIT[ch];
      matched = true;
    } else if (Object.prototype.hasOwnProperty.call(KOR_NUM_SMALL_UNIT, ch)) {
      const bufVal = flushBuf();
      const base = bufVal !== null ? bufVal : (current || 1);
      section += base * KOR_NUM_SMALL_UNIT[ch];
      current = 0;
      matched = true;
    } else if (Object.prototype.hasOwnProperty.call(KOR_NUM_BIG_UNIT, ch)) {
      const bufVal = flushBuf();
      if (bufVal !== null) current = bufVal;
      const segment = section + current;
      result += (segment || 1) * KOR_NUM_BIG_UNIT[ch];
      section = 0; current = 0;
      matched = true;
    }
  }
  const bufVal = flushBuf();
  if (bufVal !== null) current += bufVal;
  result += section + current;
  return matched ? result : null;
}

// 언어별로 자국 통화 단어를 EXCHANGE_RATE_* 전역 변수와 매칭 — 이미 사이트가 관리 중인
// 환율을 그대로 재사용함(운영자가 매일 갱신하는 그 값). "루피"처럼 여러 나라가 같은 통화명을
// 쓰는 경우가 있어(인도/네팔/스리랑카/파키스탄), 전역이 아니라 현재 UI 언어에 매인 통화만 검사함
const VOICE_LOCAL_CURRENCY = {
  zh: /元|人民币|块钱|yuan|rmb/i,
  hi: /रुपये|रुपया|rupee/i,
  vi: /đồng|dong\b/i,
  id: /rupiah/i,
  tl: /piso|peso/i,
  th: /บาท|baht/i,
  ja: /円|yen/i,
  ru: /рубл|ruble|rouble/i,
  ne: /रुपैयाँ|रुपिया/i,
  si: /රුපියල්|rupee/i,
  uz: /so'm|sum\b|сум/i,
  kk: /теңге|tenge/i,
  ky: /сом|som\b/i,
  my: /ကျပ်|kyat/i,
  bn: /টাকা|taka/i,
  ur: /روپے|rupee/i,
  km: /រៀល|riel/i,
  mn: /төгрөг|tugrik/i,
  lo: /ກີບ|kip\b/i,
};
function voiceLocalCurrencyRate(lang){
  switch (lang) {
    case 'zh': return EXCHANGE_RATE_CNY;
    case 'hi': return EXCHANGE_RATE_INR;
    case 'vi': return EXCHANGE_RATE_VND;
    case 'id': return EXCHANGE_RATE_IDR;
    case 'tl': return EXCHANGE_RATE_PHP;
    case 'th': return EXCHANGE_RATE_THB;
    case 'ja': return EXCHANGE_RATE_JPY;
    case 'ru': return EXCHANGE_RATE_RUB;
    case 'ne': return EXCHANGE_RATE_NPR;
    case 'si': return EXCHANGE_RATE_LKR;
    case 'uz': return EXCHANGE_RATE_UZS;
    case 'kk': return EXCHANGE_RATE_KZT;
    case 'ky': return EXCHANGE_RATE_KGS;
    case 'my': return EXCHANGE_RATE_MMK;
    case 'bn': return EXCHANGE_RATE_BDT;
    case 'ur': return EXCHANGE_RATE_PKR;
    case 'km': return EXCHANGE_RATE_KHR;
    case 'mn': return EXCHANGE_RATE_MNT;
    case 'lo': return EXCHANGE_RATE_LAK;
    default: return null;
  }
}

// 말한 문장에서 통화 키워드를 찾아 "1 USD = rate 단위" 환율을 반환. 없으면 null
function detectSpokenCurrencyRate(text, lang){
  if (/원|원화/.test(text)) return EXCHANGE_RATE; // KRW — 언어와 무관하게 항상 확인(참택스가 한국어 우선 서비스라 가장 흔한 케이스)
  if (/달러|dollar|usd|\$/i.test(text)) return 1; // USD — 입력칸 기준 통화라 배율 1
  const localRe = VOICE_LOCAL_CURRENCY[lang];
  if (localRe && localRe.test(text)) return voiceLocalCurrencyRate(lang);
  return null;
}

// 음성 인식 결과 문자열 → 입력칸에 넣을 "USD 백만 단위" 숫자로 최종 환산. 실패 시 null
function parseSpokenAmountToMillions(transcript, lang){
  const korValue = koreanWordsToNumber(transcript);
  const hadKoreanUnitWord = /[만억조]/.test(transcript);
  const currencyRate = detectSpokenCurrencyRate(transcript, lang);

  if (korValue !== null && (hadKoreanUnitWord || currencyRate !== null)) {
    // 한글 숫자 단어(만/억 등)로 말했거나 통화 키워드가 있으면, 이건 "총액"이지 이미 million
    // 단위인 게 아님 — 통화가 명시 안 됐는데 만/억 단위를 썼다면(예: "삼억") 한국어 화자가
    // 원화를 그렇게 부르는 게 일반적이라 원화로 간주함
    const rate = currencyRate !== null ? currencyRate : EXCHANGE_RATE;
    if (!rate) return null;
    return korValue / rate / 1000000;
  }

  const digitsOnly = transcript.replace(/[^0-9.]/g, '');
  if (!digitsOnly) return null;
  let n = Number(digitsOnly);
  if (isNaN(n)) return null;
  if (/billion/i.test(transcript)) n *= 1000; // 입력칸 기준(million) 대비 ×1000
  else if (/thousand/i.test(transcript)) n /= 1000; // 입력칸 기준(million) 대비 ÷1000
  // "million" 단어는 입력칸 기본 단위와 이미 같아서 별도 배율 처리 불필요

  if (currencyRate !== null && currencyRate !== 1) {
    // 통화 키워드는 있는데 위에서 한글 파서가 안 걸린 경우(예: "50000000원"처럼 아라비아
    // 숫자+통화 키워드 조합) — 이 숫자는 "총액"이므로 환전 필요
    return n / currencyRate / 1000000;
  }
  return n; // 통화 키워드 없음 — 기존처럼 이미 million 단위로 간주(하위호환)
}

function startAmountVoiceInput(inputId, onTyped){
  if (!SpeechRecognitionCtor) return;
  const input = document.getElementById(inputId);
  const btn = document.getElementById(inputId === 'homeAmountInput' ? 'homeAmountVoiceBtn' : 'homeAnnouncedVoiceBtn');
  if (!input) return;

  // 이미 듣고 있는 중에 다시 누르면 중지(토글) — FAQ 음성 버튼과 동일한 안전장치
  if (amountVoiceRecognition) { amountVoiceRecognition.stop(); return; }

  amountVoiceRecognition = new SpeechRecognitionCtor();
  amountVoiceRecognition.lang = FAQ_VOICE_LANG_MAP[currentLang] || 'ko-KR';
  amountVoiceRecognition.interimResults = true;
  amountVoiceRecognition.maxAlternatives = 1;

  amountVoiceRecognition.onstart = () => { if (btn) btn.classList.add('listening'); };
  amountVoiceRecognition.onresult = (e) => {
    const transcript = Array.from(e.results).map(r => r[0].transcript).join('');
    const millions = parseSpokenAmountToMillions(transcript, currentLang);
    if (millions !== null && millions > 0) {
      // 예전엔 Math.round(millions * 10000) / 10000(소수점 4자리 고정)로 반올림했는데, 이 단위는
      // "Million USD" 기준이라 4자리 반올림 격자 자체가 약 $100 단위임 — "천원"(~$0.67)·"백원"
      // (~$0.067)처럼 작은 금액은 이 격자보다 작아서 정확히 0으로 뭉개져 음성 입력이 조용히
      // 아무 반응도 안 하는 것처럼 보였음(2026-07-28 사용자 실사용 중 발견). roundAmountForInput()
      // 근처의 roundToSignificantFigures()(유효숫자 기준, 값의 크기에 비례해 반올림 단위가 같이
      // 줄어듦)로 교체 — 통화·언어와 무관하게 모든 VOICE_LOCAL_CURRENCY 언어에 동일하게 적용됨
      // (parseSpokenAmountToMillions()가 이미 통화별로 USD 백만 단위까지 환산을 끝낸 뒤라, 이
      // 반올림 자체는 어떤 통화로 말했는지와 무관한 공용 마지막 단계).
      const rounded = Math.min(roundToSignificantFigures(millions, 4), MAX_INPUT_MILLIONS);
      // parseSpokenAmountToMillions()의 결과는 항상 Million USD 단위 — 지금 화면 통화가 KRW
      // 등이면 그대로 넣지 않고 표시 단위로 환산해야 함(2026-07-28, 통화 선택기 도입과 함께 수정.
      // onTyped()가 곧바로 이 값을 다시 표시 단위 기준으로 재해석하므로 왕복이 서로 맞음)
      input.value = roundAmountForInput(usdMillionsToInputUnits(rounded, sharedInputCurrency));
      onTyped();
    }
    const lastResult = e.results[e.results.length - 1];
    if (lastResult && lastResult.isFinal) amountVoiceRecognition.stop();
  };
  amountVoiceRecognition.onerror = () => { if (btn) btn.classList.remove('listening'); amountVoiceRecognition = null; };
  amountVoiceRecognition.onend = () => { if (btn) btn.classList.remove('listening'); amountVoiceRecognition = null; };

  try { amountVoiceRecognition.start(); } catch (e) { /* 이미 시작된 세션 등 — 조용히 무시 */ }
}

