function updateFlexBox(finalEok, country){
  updateFunSummary(finalEok);
  const wonAmount = finalEok * 100000000;
  const usdAmount = wonAmount / EXCHANGE_RATE;
  const cnyAmount = usdAmount * EXCHANGE_RATE_CNY;
  const inrAmount = usdAmount * EXCHANGE_RATE_INR;
  // FLEX_REF에 21개국이 있는데(2026-07-28 17개국 추가) 여기는 원래 4개 통화만 커버해서, 새로
  // 추가된 17개국은 amountByCurrency[ref.apt.currency]가 undefined가 되어 전부 NaN으로 표시되던
  // 버그가 있었음(사용자가 키르기스스탄/방글라데시 화면에서 발견) — 나머지 통화도 전부 채움
  const amountByCurrency = {
    krw: wonAmount, usd: usdAmount, cny: cnyAmount, inr: inrAmount,
    vnd: usdAmount * EXCHANGE_RATE_VND, idr: usdAmount * EXCHANGE_RATE_IDR, php: usdAmount * EXCHANGE_RATE_PHP,
    thb: usdAmount * EXCHANGE_RATE_THB, jpy: usdAmount * EXCHANGE_RATE_JPY, rub: usdAmount * EXCHANGE_RATE_RUB,
    npr: usdAmount * EXCHANGE_RATE_NPR, lkr: usdAmount * EXCHANGE_RATE_LKR, uzs: usdAmount * EXCHANGE_RATE_UZS,
    kzt: usdAmount * EXCHANGE_RATE_KZT, kgs: usdAmount * EXCHANGE_RATE_KGS, mmk: usdAmount * EXCHANGE_RATE_MMK,
    bdt: usdAmount * EXCHANGE_RATE_BDT, pkr: usdAmount * EXCHANGE_RATE_PKR, khr: usdAmount * EXCHANGE_RATE_KHR,
    mnt: usdAmount * EXCHANGE_RATE_MNT, lak: usdAmount * EXCHANGE_RATE_LAK,
  };
  const ref = FLEX_REF[country] || FLEX_REF.kr;
  const localeStr = LOCALE_MAP[currentLang] || 'ko-KR';

  const apt = Math.floor(amountByCurrency[ref.apt.currency] / ref.apt.price);
  const car = Math.floor(amountByCurrency[ref.car.currency] / ref.car.price);
  const coffeeCups = Math.floor(amountByCurrency[ref.coffee.currency] / ref.coffee.price);
  const coffeeYears = Math.floor(coffeeCups / 3 / 365);

  document.getElementById('flex-apt-label').textContent = ref.apt.label();
  document.getElementById('flex-car-label').textContent = ref.car.label();
  document.getElementById('flex-coffee-label').textContent = ref.coffee.label();

  // 2026-07-27: 국가별 커스텀 애니메이션 대신 "가벼운 공통 모션"(사용자 요청) — 숫자는 0에서
  // 목표값까지 카운트업되고, 아이콘은 barIconPop으로 살짝 통통 튐. 셋 다 같은 로직이라
  // 나라마다 새로 만들 게 없음.
  const aptUnit = pickLang('채', ' units', '套', ' căn', ' หลัง', ' шт.', { km:'ខ្នង', ne:'वटा', id:' unit', my:' လုံး', si:'ක්', uz:' ta', mn:' айл', kk:' пәтер', ky:' батир', ur:' یونٹس', bn:'টি', lo:' ຫຼັງ', ja:'戸', ar:' وحدة', hi:' यूनिट', fr:' logements', tl:' unit' , pt: ` unidades`, es: ` unidades`, uk: ` одиниць`, tet: ` unidade`});
  const carUnit = pickLang('대', ' cars', '辆', ' chiếc', ' คัน', ' шт.', { km:'គ្រឿង', ne:'वटा', id:' unit', my:' စီး', si:'ක්', uz:' ta', mn:' машин', kk:' көлік', ky:' машина', ur:' گاڑیاں', bn:'টি', lo:' ຄັນ', ja:'台', ar:' سيارة', hi:' गाड़ियाँ', fr:' voitures', tl:' kotse' , pt: ` carros`, es: ` autos`, uk: ` авто`, tet: ` karreta`});
  const cupUnit = pickLang('잔', ' cups', '杯', ' ly', ' แก้ว', ' чашек', { km:'ពែង', ne:'कप', id:' cangkir', my:' ခွက်', si:'ක්', uz:' finjon', mn:' аяга', kk:' кесе', ky:' чыны', ur:' کپ', bn:'কাপ', lo:' ຈອກ', ja:'杯', ar:' كوب', hi:' कप', fr:' tasses', tl:' tasa' , pt: ` xícaras`, es: ` tazas`, uk: ` чашок`, tet: ` xíkara`});
  // 연 단위 문장("하루 3잔씩 N년")인지 잔 수만 표시할지는 최종값 기준으로 한 번만 정하고, 카운트업
  // 도중에는 그 문구 형식을 그대로 두고 숫자(n)만 0→목표치로 바꿔치기함 — 애니메이션 중간에
  // 문장 형태 자체가 바뀌면(예: 잔→년) 어색해 보이기 때문
  const useCoffeeYears = coffeeYears > 0;
  function buildCoffeeText(n){
    return useCoffeeYears
      ? pickLang(`하루 3잔씩 ${n.toLocaleString(localeStr)}년`, `3/day for ${n.toLocaleString(localeStr)} years`, `每天3杯，喝${n.toLocaleString(localeStr)}年`, `3 ly/ngày trong ${n.toLocaleString(localeStr)} năm`, `วันละ 3 แก้ว เป็นเวลา ${n.toLocaleString(localeStr)} ปี`, `по 3 в день в течение ${n.toLocaleString(localeStr)} лет`, { km:`ថ្ងៃមួយ 3 ពែង អស់រយៈពេល ${n.toLocaleString(localeStr)} ឆ្នាំ`, ne:`दिनको ३ कपका दरले ${n.toLocaleString(localeStr)} वर्ष`, id:`3/hari selama ${n.toLocaleString(localeStr)} tahun`, my:`တစ်နေ့ ၃ ခွက်နှုန်းဖြင့် ${n.toLocaleString(localeStr)} နှစ်`, si:`දිනකට කෝප්ප 3 බැගින් වසර ${n.toLocaleString(localeStr)} ක්`, uz:`kuniga 3 tadan ${n.toLocaleString(localeStr)} yil`, mn:`өдөрт 3-аар ${n.toLocaleString(localeStr)} жил`, kk:`күніне 3-тен ${n.toLocaleString(localeStr)} жыл`, ky:`күнүнө 3төн ${n.toLocaleString(localeStr)} жыл`, ur:`روزانہ 3 کپ کے حساب سے ${n.toLocaleString(localeStr)} سال`, bn:`দিনে ৩ কাপ করে ${n.toLocaleString(localeStr)} বছর`, lo:`ວັນລະ 3 ຈອກ ເປັນເວລາ ${n.toLocaleString(localeStr)} ປີ`, ja:`1日3杯で${n.toLocaleString(localeStr)}年分`, ar:`3 أكواب يومياً لمدة ${n.toLocaleString(localeStr)} سنة`, hi:`रोज़ 3 कप के हिसाब से ${n.toLocaleString(localeStr)} साल`, fr:`3/jour pendant ${n.toLocaleString(localeStr)} ans`, tl:`3/araw sa loob ng ${n.toLocaleString(localeStr)} taon` , pt: `3/dia por ${n.toLocaleString(localeStr)} anos`, es: `3/día durante ${n.toLocaleString(localeStr)} años`, uk: `3 на день протягом ${n.toLocaleString(localeStr)} років`, tet: `3/loron ba tinan ${n.toLocaleString(localeStr)}`})
      : n.toLocaleString(localeStr) + cupUnit;
  }

  const aptEl = document.getElementById('flex-apt');
  const carEl = document.getElementById('flex-car');
  const coffeeEl = document.getElementById('flex-coffee');
  animateFlexNumber(aptEl, apt, n => n.toLocaleString(localeStr) + aptUnit);
  animateFlexNumber(carEl, car, n => n.toLocaleString(localeStr) + carUnit);
  animateFlexNumber(coffeeEl, useCoffeeYears ? coffeeYears : coffeeCups, buildCoffeeText);

  [aptEl, carEl, coffeeEl].forEach((el, i) => {
    el.classList.remove('val-pop');
    const icon = el.closest('.flex-row')?.querySelector('.flex-icon');
    if (icon) icon.classList.remove('icon-pop');
    void el.offsetWidth; // 강제 리플로우 — 연속 갱신 때도 매번 다시 재생되도록
    el.classList.add('val-pop');
    if (icon) {
      icon.style.animationDelay = (i * 80) + 'ms';
      icon.classList.add('icon-pop');
    }
  });
}

